globalThis.ANDE_CHUNKS["5890dd0db337c9ba3f3ea83fed2b0efcadf8eda8f9570511a9d73212e69f9d30"] = [{"id":"tongyi_social:100009980051","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-多模态交互算法专家-Qwen Audio","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100009980051&track_id=SSP1791223736998pFVIsmISsK6916","duty":"1. 负责Token Foundry多模态口语交互的算法研发，通过深入理解全链路多模态交互技术，推进大模型增强的语言交互技术能力建设。\n2. 多模态交互：\n（1）端到端多模态联合建模 - 语音/视觉/文本等模态融合并应用于人机交互场景。\n（2）多模态交互应用算法 - 意图动态规划、多智能体协作、多任务推理、主动交互。\n（3）多模态对话系统设计 - 多轮交互状态管理、情境感知、情感理解及生成控制。\n3. 音视频内容理解：\n（1）转写内容后处理 - 书面化、标点、分段分章节。\n（2）音视频分析 - 分角色、语种判别、视频场景划分。\n（3）口语内容长篇章理解及生成。\n4. 探索多模态口语交互技术落地于实际应用场景，包括但不限于：\n（1）消费电子-智能穿戴实时交互、手机多模态助手、具身机器人环境感知。\n（2）内容消费-音视频媒资、会议场景、电销通话多模态理解等。\n5. 持续关注行业前沿动态，通过专利申请、论文和技术报告等形式提升团队的技术影响力。","requirements":"1. 计算机或通信专业硕士及以上学历。\n2. 具有2年以上多模态交互或语言理解算法研发经验，以下领域至少精通一项：\n（1）多模态联合建模（语音+视觉/文本等）。\n（2）对话系统设计及开发。\n（3）口语语言理解。\n（4）多智能体交互决策。\n3. 精通基于深度神经网络的机器学习算法，熟悉Transformer、GPT、LLM等算法原理，掌握 AI 产品开发的开源工具和框架，具备优秀的编程能力。\n4. 具备以下经验者加分：\n（1）在顶级会议或期刊上发表过相关领域的论文。\n（2）有业界前沿的语音多模态交互或数字人交互系统的算法经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100013220008","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-模型研发工程师（工程方向）-AI Infra团队","city":"北京/杭州/上海","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100013220008&track_id=SSP1791223736998OtCbuPMcef3344","duty":"岗位职责：\n● 构建统一的运行环境、配置管理和执行框架，支撑模型 Agent 能力的持续迭代与增强；\n● 建设 Benchmark 的构建、接入与自动化体系，提供上下文轨迹分析与全链路 LLM 评估能力，驱动模型能力持续演进；\n● 与infra基础设施团队紧密协作，构建面向 AI 场景的底层支撑能力；\n● 与研究员深度合作，共同实现 LLM 能力的持续领先。","requirements":"● 扎实的编程功底，在以下至少一个方向有深入理解或实践经验：云计算、多模态理解、安全、Agent、智能办公等；\n● 自驱力强，持续学习的能力、不断追求卓越；\n● 有较强的问题分析和定位能力，能剥丝抽茧深入问题本质；\n● 优秀的问题抽象能力和团队协同意识。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100046140009","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-多模态算法专家/高级专家（理解与生成）-未来生活实验室","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100046140009&track_id=SSP1791223736998GdZBgKLkav7873","duty":"1. 多模态理解：负责图文/视频/音频理解相关的算法研发，提升模型对复杂多模态场景的语义分析和推理能力。\n2. 多模态生成：开发基于 Diffusion Model 或 Autoregressive 架构的生成算法（如 Text-to-Image, Text-to-Video），优化生成的质量、多样性与可控性。\n3. 统一架构：设计并研发多模态大模型理解和生成的统一架构，通过高效Transformer结构、位置编码优化等，实现对图像、视频、文本的深度语义理解与高保真内容生成。","requirements":"1. 自然语言处理、机器学习、数据挖掘、人工智能等相关专业的硕士生/博士生；\n2. 熟练掌握Tensorflow、Pytorch等深度学习框架，扎实的编程基础，具备独立的算法实现能力；\n3. 有LLM实操经验，参与过大模型预训练，SFT，RLHF等项目；有垂域基座模型项目经验者优先，参与过大模型结合搜广推项目者优先；\n4. 良好的逻辑分析能力和数理基础，对算法原理及应用有较深入的理解，在人工智能相关的各类国际顶级会议/期刊中发表过论文者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100015380001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-算法专家-多模态智能体","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100015380001&track_id=SSP1791223736998kJaCldFogp2197","duty":"1. 探索研究多模态大模型、GUI agent、agentic RL、long-horizon agent、self-improving agent等前沿技术。\n2. 参与研发多模态、全模态大模型等下一代人工智能核心技术,重点探索面向真机环境的多模态智能体大规模强化学习与自我演进。\n3. 参与 GUI 垂类基座模型与真机 agent 系统的迭代,推动核心能力达到业界第一梯队。\n4. 跟踪研究多模态大模型前沿进展,参与 AIOS 等 to C / to B 重点业务场景的端到端落地。","requirements":"1. 计算机科学、人工智能、机器学习或相关领域的硕士或博士学位。\n2. 在多模态、大语言模型、Agent、强化学习、机器学习等一个或多个领域有较深入的研究。\n3. 具有出色的分析与解决问题能力,能深入解决大模型训练与 agent 系统落地中存在的问题,具备自主探索解决方案的能力。\n4. 能够积极创新,乐于面对挑战,负责敬业,具备优秀的团队合作精神,一起探索新技术、推进技术进步。\n\n加分项\n1. 具有扎实的机器学习基础与优秀的基础算法能力,在 NeurIPS、ICLR、ICML、ACL、CVPR 等顶级会议/期刊上发表论文者优先。\n2. 具有优秀的代码能力,在 ACM/ICPC、NOI/IOI、Top Coder、Kaggle 等比赛获奖者优先。\n3. 在多模态、大模型、基础模型、世界模型、RL 领域,主导过大影响力项目者优先。\n4. 在 GUI agent / mobile agent / computer-use agent、真机或仿真环境建设、大规模 RL 训练系统等方向有实际经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100007780004","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-云端Agent技术专家-北京/杭州","city":"北京/杭州","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100007780004&track_id=SSP1791223736998IbQxMMCTkH6969","duty":"1.  面向ToB行业场景（如AI手机等），设计并构建可扩展、高可用的Agent编排系统，支撑多模态交互系统中复杂任务的自动化执行。\n2.  深度整合阿里集团内部丰富的Agent能力，同时对接第三方生态服务，打造统一的行业级Agent应用。\n3.  制定标准化的工具描述协议、Agent接入规范与开发者工具链（SDK/CLI/调试平台），降低内外部生态伙伴的接入门槛。\n4.  针对移动端等资源受限环境，优化Agent调用链路的性能、延迟与鲁棒性，支持离线、弱网、低功耗等边缘场景下的可靠运行。","requirements":"1.  计算机科学、软件工程或相关专业硕士及以上学历，3年以上后端系统或平台型产品研发经验。\n2.  熟悉大模型驱动的Agent架构，具备Task Planning、Function Calling、Tool Use、ReAct等机制的实际开发或集成经验。\n3.  精通至少一种主流后端语言（如Java、Go、Python），熟悉微服务架构、分布式系统、消息中间件（如RocketMQ、Kafka）及API网关技术。\n4.  了解LangChain、LlamaIndex、AutoGen、Semantic Kernel 或类似Agent框架，有自研Agent调度引擎经验者优先。\n5、有大模型Agent应用的规模化落地经验。主导或深度参与过先进Agent Harness架构（如计划-执行、反思、多智能体协同等）的设计与实现，对Agent的规划、工具调用、状态管理有系统性认知。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100046200005","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-业务HRG专员-AI大模型方向","city":"杭州","category":"综合类-人力资源","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100046200005&track_id=SSP1791223736998rEzuuJMWvW3524","duty":"我们希望你深入大模型业务，作为业务Leader的组织与人才伙伴，围绕AI大模型业务战略，推动组织能力建设、关键人才供给与保留、文化机制建设及数据化运营，以组织效能支撑业务目标实现。\n\n1、战略落地与组织设计：深入理解业务战略，推动目标拆解、落地、阶段性复盘与调整；结合行业趋势、竞对动态及组织发展阶段，设计并推动适配的组织策略。\n2、人才供给与发展：制定岗位与人才标准，持续提升人才密度；推动关键产研人才，尤其是AI大模型领域人才的即时供给与保留，促进人才结构持续优化。\n3、组织文化与机制建设：以身作则践行文化价值观，增强团队归属感与凝聚力；围绕业务场景建设沟通、决策和复盘机制，完善激励与约束体系，激发组织活力；妥善处理员工事件与合规事项，营造积极正向的组织氛围。\n4、数据驱动与效能提升：通过数据看板和数字化工具识别组织问题，形成高质量洞察并推动解决；推动数据系统产品化建设，帮助业务减负降本。","requirements":"1、5年以上工作经验，其中3年以上HRBP/HRG经验。\n2、具备研发、算法等技术团队的HRBP/HRG经验，对AI/大模型等技术方向有一定认知，理解技术团队的工作方式及人才特点。\n3、精通人才盘点、组织诊断、机制设计等专业方法，能够识别关键问题并推动解决方案落地。\n4、能够与业务Leader就组织策略开展高质量对话，预判关键问题，并独立形成系统性解决方案。\n5、具备强烈的好奇心和学习敏锐度，主动拥抱新事物、新趋势，愿意打破惯性；对AI有真正的好奇与一定理解。\n6、眼中有事、心中有人，既围绕战略目标开展工作，也关注组织中的人；具备良好的沟通能力，能够快速建立信任与连接。\n7、具备较强的韧性和抗压能力，能够适应不确定性与挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100011160010","sourceKey":"tongyi_social","company":"通义","title":"Token Foundary事业部-音频算法专家/高级专家-未来生活实验室","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100011160010&track_id=SSP1791223736998mERXESTsQz8311","duty":"1、研发前沿的音频大模型 (Audio-LLM)，实现语音识别 (ASR)、语音合成 (TTS) 与音频理解的端到端融合。\n2、优化多语种、情感化及高表现力的语音生成，提升在复杂环境（噪声、多人交谈）下的语义提取鲁棒性。\n3、设计并优化多模态音乐生成模型，涵盖风格、韵律、和声、节奏等多维度生成任务。\n4、探索音频 Tokenizer 优化，实现音频与 LLM 符号空间的对齐。","requirements":"1、熟悉主流音频架构（如 Whisper, VITS, AudioLM, Vall-E，CosyVoice）；\n2、精通音频信号处理及神经编解码器（Neural Codec）；\n3、有全双工、超低延迟流式语音交互系统（Real-time Interactive Voice）的落地经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:7000035904","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-多模态理解算法专家-杭州/北京","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=7000035904&track_id=SSP1791223736998vGQjTopVCJ5520","duty":"1、探索研究多模态理解、计算机视觉、自然语言处理等前沿技术；\n2、参与研发多模态、全模态大模型等下一代人工智能核心技术，探索大规模/超大规模多模态理解与生成统一的基础模型，提升大模型能力；\n3、负责跟踪和研究多模态大模型前沿技术调研、落地、对业务进行优化。","requirements":"1、计算机科学、人工智能、机器学习或相关领域的硕士或博士学位；\n2、在多模态、计算机视觉、NLP、AIGC、计算机图形学、机器学习等一个或多个领域有较深入的研究；\n3、具有出色的分析、解决问题的能力，能深入解决大模型训练、应用存在的问题，有自主探索解决方案的能力者；\n4、能够积极创新， 乐于面对挑战， 负责敬业，优秀的团队合作精神，一起探索新技术，推进技术进步。\n加分项：\n1、具有优秀的基础算法、扎实的机器学习基础，在CVPR、ECCV、ICCV、NeurIPS、ICLR、ICML、SIGGRAPH或SIGGRAPH Asia等顶级会议/期刊上发表论文者优先；\n2、有多模态数据处理，清洗，标注经历的优先；\n3、具有优秀的代码能力，在ACM/ICPC、NOI/IOl、Top Coder、Kaggle等比赛获奖者优先；\n4、在多模态、大模型、基础模型、世界模型、RL、渲染生成领域，主导过大影响力项目者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100042760002","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-数据科学专家-Qwen基础模型","city":"北京/杭州/上海","category":"技术类-数据","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100042760002&track_id=SSP1791223736998eriKOxkUzt3787","duty":"1. 建立coding / cowork领域各行业专业任务的大模型agent算法内部评测体系，帮助快速发现模型短板和缺点，提升模型表现。\n2. 推动算法研究、agent infra开发、数据团队协作统一进行标注任务的需求提出、标准制定、过程管理、数据验收等全链路工作，提供可靠的数据保障。\n3. 结合已有数据和行业发展趋势与算法codesign优化策略、设计实验并完成实验评测分析。\n4. 海内外模型厂商的行业数据监控分析，指导模型迭代。","requirements":"1. 硕士及以上学历。\n2. 有coding / cowork各垂直行业从业经验和理解。\n3. 有一定数理统计基础和代码基础，具备较强的逻辑思维能力。\n4. 有较强的沟通和项目协调能力，能够在不同角色的合作团队之间起到沟通桥梁作用。\n5. 对大模型发展具备较深入了解，对Agent使用和优化有Sense。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100022900005","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-AI for Science/Engineering 算法专家-Qwen模型训练","city":"北京/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100022900005&track_id=SSP1791223736998QRTfpxrzpu7559","duty":"1. AI for Science 方向\n（1）包括但不限于构建面向生物（基因组分析、蛋白质功能预测等）、化学（分子性质预测、逆合成规划等）等领域的 Agent 系统、Science harness，整合领域专用工具与知识库。\n（2）设计科学推理评测基准，评估并提升模型在自动探索、工具调用、实验设计等任务上的表现，同时构造训练数据与环境优化Qwen模型在科学领域的表现。\n（3）探索 AI 驱动的科学发现闭环：假设生成、实验设计、 结果验证、知识更新，提升模型科学领域Auto Research能力。\n2. AI for Engineering 方向\n（1）将大模型应用于芯片设计EDA、工业设计CAD、金融工程、工业自动化、kernel调优等工程问题，训练模型在真实生产环境中的自进化能力，通过持续学习发掘更优算法与设计。\n（2）研究基于self-evolving、long-horizon、multi-agent等范式的能力增强方法，提升Qwen模型在工程优化领域的表现。\n3. 与跨学科团队紧密协作，推动研究成果在真实科研或工程场景中的验证与落地。\n4. 跟踪科学与工程智能及相关方向的前沿进展，围绕关键问题开展算法创新、实验分析与技术沉淀。","requirements":"1. 计算机、人工智能、自动化等相关专业本科及以上学历，硕士/博士优先。\n2. 满足以下条件之一者优先：\n（1）在科学研究或复杂工程领域具备较强的专业理解与积累，能够准确把握领域内的重要问题、核心参与方、关键数据资源和前沿发展方向；在相关方向具备较强的行业敏感度。\n（2）已在实际科学研究或工业领域将大模型深度融入工作流程，能够从领域问题出发完成方法设计、方案落地与效果迭代，并对AI与领域交叉方向的发展趋势形成较成熟的判断。\n3. 极强的求知欲与学习能力，对新技术保有好奇心；逻辑清晰，善于独立思考并反思总结；具备良好的沟通能力和团队协同意识。\n4. 熟悉Python；具备较强的工程实现能力。\n5. 具备较强科研能力或技术产出能力，有高水平论文、开源项目、竞赛成绩或实际落地成果者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100022900004","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-模型自进化算法专家-Qwen模型训练","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100022900004&track_id=SSP1791223737367qPRmiFYCiQ6816","duty":"1. 围绕模型自进化方向开展算法研究与系统研发，探索大模型能力自动演进的关键路径。\n2. 聚焦Agent任务，为模型注入自动迭代RL/SFT训练数据的能力，包括Agent环境/query/verifier合成、筛选、训练、反馈闭环优化，通过多轮迭代提升训练数据质量。\n3. 为模型注入自动挖掘CPT/PT训练数据的能力，提升预训练和持续训练数据的知识覆盖度、有效性与任务适配性。\n4. 为模型注入自动化训练与自动化Infra调优能力，包括Verl、Megatron等框架的训练策略优化、RL超参搜索、训练稳定性提升、SGLang、vLLM推理效率优化等，提升模型研发效率和性能上限。\n5. 研究基于self-evolving、long-horizon等范式的能力增强方法，提升模型在自迭代任务中的长期规划、任务分解、多步执行与自主反馈优化能力。\n6. 跟踪相关领域前沿进展，结合实际问题开展算法创新、实验验证和系统落地，沉淀可复用的方法与能力。","requirements":"1. 计算机、人工智能、自动化等相关专业本科及以上学历，硕士/博士优先。\n2. 具备扎实的机器学习、深度学习基础，熟悉大模型训练、对齐、微调或推理优化相关技术。\n3. 实现过有效的自动化数据构造Pipeline优先。\n4. 实现过自动化训练、超参数优化、训练系统或推理框架优化优先。\n5. 极强的求知欲与学习能力，对新技术保有好奇心；逻辑清晰，善于独立思考并反思总结；具备良好的沟通能力和团队协同意识。\n6. 熟悉Python；具备较强的工程实现能力。\n7. 具备较强科研能力或技术产出能力，有高水平论文、开源项目、竞赛成绩或实际落地成果者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100022940002","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型算法专家-Qwen Agent","city":"北京/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100022940002&track_id=SSP1791223737367aLjIScRsnL3067","duty":"1. Agent模型后训练： 负责大模型在Agent场景下的后训练（Post-training）工作，提升模型在复杂Agent任务中的表现。\n2. 强化学习与RL探索： 设计并优化基于强化学习（RL）的Agent训练框架，提升模型的长期规划能力、试错反思能力及工具调用准确率。\n3. 核心能力构建： 针对Agent的核心能力进行专项模型训练与对齐优化。\n4. 行业解决方案落地： 深入理解具体行业的业务痛点，将Agent模型能力与行业Know-how结合，设计并落地端到端的行业Agent解决方案。\n5. 前沿技术追踪： 跟踪学术界和工业界在LLM Agent、RLHF、后训练领域的最新进展，将前沿技术转化为团队的工程与算法资产。","requirements":"【基础要求】\n1. 计算机科学、人工智能、数学或相关专业硕士及以上学历。\n2. 具备扎实的理论基础，熟悉Transformer架构及大模型底层原理。\n3. 具备优秀的编程习惯和工程实现能力，熟悉 PyTorch 等主流深度学习框架。\n【核心技能与经验】\n1. 深入理解大模型后训练流程，有丰富的 SFT、RLHF、PPO、DPO 等算法的实操经验；熟悉强化学习理论，有将 RL 应用于 LLM 或 Agent 决策过程的实战经验。\n2. 熟悉主流 Agent 框架与范式，有针对 Agent 特定能力进行模型微调或训练的经验。\n3. 熟悉大模型分布式训练框架，有大规模集群上的模型训练与调优经验。\n【加分项】\n1. 对 AI Agent 在真实行业场景中的应用有强烈的好奇心和探索欲，不局限于“刷榜”，更关注技术如何解决实际业务问题。\n2. 在知名大模型开源项目或 Agent 框架中有核心代码贡献。\n3. 有具体行业大模型或 Agent 落地经验者优先。\n【软性素质】\n1. 具备极强的自驱力和解决复杂问题的能力，能够在模糊的业务场景中找到技术突破口。\n2. 优秀的沟通协作能力，能够与工程团队、产品团队及业务方高效协同，推动项目落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100043860002","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-模型研发工程师（Harness 方向）-AI infra团队","city":"北京/杭州/上海","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100043860002&track_id=SSP1791223737367ayuHbZzYrz7502","duty":"● 构建业界先进的 Harness 框架，持续提升上下文压缩与管理、长期记忆、长程任务规划、Multi-Agent 协作等核心能力；\n● 深入理解模型能力边界，通过 Harness 层的策略设计与工程优化，与模型协同进化，保持产品竞争力。","requirements":"● 熟悉 LLM 与 Agent 的机制和原理，具备丰富的理论和工程实践经验；\n● 熟悉业界代表性 Harness 项目，具备优秀的抽象和系统设计能力；\n● 良好的跨团队协作能力，扎实的编程功底；\n● 对细节有持续探究的耐心，具备严谨的逻辑推理和问题甄别能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100043700004","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型算法工程师-千问文档智能","city":"杭州","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100043700004&track_id=SSP1791223737367kRUUwJpFuL2364","duty":"1. 负责千问文档AI模型的技术创新和研发，围绕文档识别解析、理解推理与创作生成，建设和升级Qwen-OCR、Qwen-Doc等模型能力；重点探索复杂版面、文字与表格识别、图片与图表解析、公式及层级结构还原、多页及超长文档理解、信息抽取与结果溯源等关键技术，持续提升模型效果、效率和泛化能力。\n2. 负责文档智能Agent及数据—模型—评测闭环建设，开展文档领域数据挖掘与合成、全尺寸模型训练、SFT/RL、长程推理、Verifier/Rubric及自动化评测等算法研发；提升模型的指令遵循、事实一致性、复杂任务规划和自校验能力，推动文档AI从单点能力向端到端Agent演进。\n3. 推动相关技术在千问模型与文档智能产品中落地，支撑ParseX文档识别解析、合同审核、PPT创作等产品方向，并服务千问办公、千问AI平台、千问App等业务场景，解决真实业务中的复杂文档问题，持续提升产品效果、服务稳定性和规模化调用效率。","requirements":"1. 本科及以上学历，计算机科学、人工智能、机器学习、模式识别、数学等相关专业优先；具备扎实的机器学习、深度学习和大模型基础。\n2. 对以下一个或多个方向有完整研究经历或工业界落地经验：多模态大模型、OCR与文档解析、文档理解与信息抽取、长上下文推理、Agent、文档生成、Verifier/Reward Model、大模型训练与对齐；有3年以上相关工作经验者优先。\n3. 熟悉主流大模型训练和harness框架及大模型训练技术，具备数据构建、模型训练、评测分析、推理优化和服务落地的端到端实践能力；能够针对复杂版面、长尾数据和超长文档等问题设计系统性解决方案。\n4. 具备独立思考和系统性研究能力，对技术与产品效果有较强的结果意识；敢于挑战现有范式，能够从真实业务问题出发完成算法定义、实验验证、工程实现和规模化落地。\n5. 【加分项】在国际顶级会议或期刊，如ICLR、NeurIPS、ICML、ACL、CVPR、ICCV、ECCV等发表过论文；在OCR、文档智能或多模态相关竞赛中取得优秀成绩；拥有高影响力开源项目；具备大型模型训练、企业级文档产品或高并发在线服务经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100043860001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-模型研发工程师（模型研究平台方向）-AI Infra团队","city":"北京/杭州/上海","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100043860001&track_id=SSP1791223737367rsszSomfyr6650","duty":"● 构建面向研究员的一体化工作台，贯通全链路模型研发过程，持续提升研发效率；\n● 建设全链路的数据管理与管控系统，以数据驱动研发全过程；\n● 持续提升模型各阶段的自动化水平，推动研发流程的持续演进；\n● 与infra基础设施团队和研究员深度共建，实现研发效能的突破性演进。","requirements":"● 卓越的代码能力、系统设计能力和工程优化能力；\n● 丰富的大规模分布式系统研发经验；\n● 积极主动，负责到底，快速迭代和持续演进；\n● 优秀的合作协同意识，乐于探索未知领域。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100011240003","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-世界模型算法专家/高级专家 (World Model)-未来生活实验室","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100011240003&track_id=SSP1791223737367jumZOIpJpY9180","duty":"1. 负责研发大规模世界模型，提升模型对真实世界动态变化的建模能力。\n 2. 研究可规模化的世界模型架构，解决世界模型在长程预测中的物理一致性问题和长期记忆等问题。\n 3. 构建世界模型数据体系，探索世界模型在参数与数据规模上的 Scaling Laws。\n 4. 构建可交互的世界模型系统，并推动技术在实际产品中的落地。","requirements":"1.  计算机、人工智能、自动化等相关专业。\n2.  在多模态大模型和生成式模型（扩散/自回归模型）上有资深背景，对前沿进展和领域问题有深入理解。\n3. 具有主流大模型的实战经验 (视频生成/VLM/LLM/LMM)，有国际高影响力的项目成果。\n4.  对 AGI 有极强的热情，能够从第一性原理出发解决世界模型领域问题。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100023000008","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-Cowork Agent算法专家-Qwen基础模型训练","city":"北京/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100023000008&track_id=SSP1791223737367MPzvySRLfE8364","duty":"推动在各个行业专家领域高生产力价值Cowork Agent的构建与实践落地，让模型在Agent环境中完成现实世界的真正复杂任务，持续提升模型在真实、高经济价值任务中的表现，拓展大模型实际能力边界。\n1. Envs/Harness Building & Generalization：复现并维护高可靠性主流Harness环境，提升模型在不同Harness场景下的泛化能力；同步探索Qwen Frontier Harness设计，探索Loop Engineering、Multi-Agent 与 Auto-Harness，与算法/数据链路 codesign 实现更好效果。\n2. Data Design & Scaling：挖掘金融、量化、法律、医疗、设计、数据分析、工业、工程等场景下的高价值数据和workflow，探索数据Pattern演化，User-Centric Data优化，General Long-Horizon Data Pipeline构建；在CPT/SFT/RL端到端验证配比/学习策略，优化模型端到端长程的行业Agent解决方案。\n3. Agentic Rewarding System：构建面向真实Agentic任务的General Verifier，设计Evolving Rubrics、Code Verifier、实现Outcome & Process Level 数据监督与自动化Rewarding，User model Rewarding。\n4. Real World RL：基于现实环境、现实任务的大规模Agentic RL训练，探索CPT->RL的端到端Scaling Law，Multi-step Rewarding Shaping，Agentic Behavior Learning。","requirements":"1. 来自全球Top高校计算机科学、人工智能、机器学习、深度学习、软件工程或相关领域应届博士/顶尖硕士毕业生。\n2. 在大语言模型或多模态大模型领域有扎实的理论基础和实践经验，在深度学习、大规模模型训练、优化算法、生成式模型、自监督学习等至少一个领域中具有行业影响力的创新性成果。\n3. 在国际顶级计算机会议/期刊以一作身份发表过多篇高水平论文，或在开源社区、竞赛中展示出引领性的研究成果。\n4. 具备扎实的代码功底，熟悉主流深度学习框架，能够高效实现复杂模型结构并进行大规模模型训练（曾参与千卡集群项目者优先）；ACM/ICPC，topcoder等编程比赛获奖者优先。\n5. 对AI技术充满好奇心，持续关注前沿领域，具备独立思考能力和系统性研究思维，敢于挑战现有范式，有志于定义下一代基础模型的进化方向；能够独立应用技术解决复杂问题，主导或深度参与过有行业有影响力项目的人选优先。\n6. 具备优秀的跨团队协作和沟通能力，能够与工程、产品等团队紧密合作，推动研究成果快速落地并产生实际影响力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100034340001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-预训练模型评测算法工程师-Qwen基础模型","city":"杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100034340001&track_id=SSP1791223737367xTxZioXSfP5971","duty":"1. 针对预训练（含mid-training，下同）模型在coding，cowork，长尾知识，长文本能力等方面的弱点，设计并构建具有可扩展性的自动化评测方案及高质量数据集。\n2. 整合高质量公开评测集和私有评测集。为不同训练阶段、不同领域、不同优化目标（模型结构/数据配比/主线模型迭代）定制评测方案，挑选质量最高、领域最合适、区分度最好的评测数据与指标。\n3. 与工程团队合作提高评测系统的效率与稳定性，完善评测故障分析与检测，并推动文本评测与Agent评测的自动化与可视化。\n4. 设计Pretrain + LightSFT的数据配比和训练策略并搭建相关pipeline，实时检测预训练模型的agentic潜力。\n5. 设计面向后训练agent能力导向的预训练评测范式，挖掘高预测性的external metrics以及internal indicators，寻找上限更高、潜力更强的预训练基座。","requirements":"1. 本科及以上学历，计算机、人工智能、软件工程、数学、自动化等相关专业优先。\n2. 优秀的数据sense，扎实的算法基础和 (vibe-) coding动手能力。具备对基础模型与Agent研发的热情，认同评测对模型优化的巨大价值。\n3. 有基模团队实习经历或相关领域顶会论文优先。有LLM评测经验，Benchmark构建经验或数据合成经验优先。\n4. 具备跨学科视野、良好的沟通能力和团队协作精神，能与数据、工程团队紧密配合推动落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100011260006","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-多模态大模型数据评测专家-未来生活实验室","city":"北京/杭州","category":"技术类-综合","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100011260006&track_id=SSP1791223737367QmCToLgZUo9425","duty":"1、评测体系建设\n深入理解公司 AI 产品业务场景，结合多模态大模型技术发展趋势，设计并持续完善模型评测体系，包括评测维度、指标定义、评测流程与方法论，确保评测结果能够客观反映模型能力变化与关键问题。\n2、数据与评测标准建设\n负责多模态大模型训练与评测数据的质量体系建设，包括数据标注规范制定、评测标准设计及数据集构建与优化，沉淀高质量数据资产，为模型训练与评测提供可靠基础。\n3、模型评测与效果分析\n联合产品与算法团队开展离线评测、场景评测及对比评测，系统分析模型表现与能力边界，输出结构化评测报告，支持模型迭代与产品优化。\n4、评测场景与Benchmark构建\n围绕核心业务场景构建评测任务与Benchmark体系，持续扩展评测覆盖范围，确保评测体系能够真实反映用户场景与模型能力。\n5、数据驱动的优化闭环与行业对标\n与算法、产品和数据团队协作，通过评测定位模型问题并推动数据补充与模型优化，建立“评测—分析—优化—复评”的迭代闭环，同时持续跟踪行业评测方法与Benchmark，优化内部评测框架。","requirements":"1、本科及以上学历，影视、编导、美学设计等相关专业优先；\n2、具有2年及以上大模型项目经验，作为多模态大模型的深度用户，对文生图，文生视频大模型有丰富的实际操作经验，能提供对应的AIGC生图/生视频的作品优先；\n3、有较好的美学基础，对镜头语言，分镜脚本，故事板等多个环节有所了解或对艺术美学有专项经验优先；\n4、具备良好的数据分析能力，掌握Python、Excel等数据分析工具优先；\n5、拥有良好的沟通协调能力和团队合作精神，能够与不同部门有效地合作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100030500001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-基础大模型预训练数据算法-Qwen","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100030500001&track_id=SSP1791223737367AeMVgASILv6344","duty":"1. 负责Qwen大模型预训练数据的算法设计与体系建设，面向海量文本、代码、多模态等数据，开展数据采集扩充、质量评估、筛选配比和合成优化，建设高质量、可持续迭代的预训练数据管线；\n2. 持续建设面向mid-train阶段的模型驱动的合成与质检链路，围绕知识、推理、代码、长文、Agent、多模态等核心能力方向，形成数据生产、质量控制与训练反馈的闭环优化机制，不断提升数据密度、能力针对性与最终训练收益；\n3. 持续完善数据实验与验证链路，构建覆盖不同模型参数规模的数据scaling研究策略，系统分析数据策略在不同参数规模下的收益迁移与效果一致性，同时丰富预训练评测体系，跟进大模型前沿技术研究，推动预训练数据闭环迭代，打造业内领先的数据算法能力。","requirements":"1. 毕业于全球Top高校计算机科学、人工智能、机器学习、软件工程或相关专业，具备扎实的学术基础与技术能力，博士优先；\n2. 在大语言模型或多模态大模型相关方向具备深厚的理论基础和实践经验，在深度学习、优化算法、大规模数据处理、大规模模型训练等领域取得过突出成果；\n3. 具备优秀的研究与工程能力，在顶级会议/期刊发表过高水平论文，或在开源、竞赛、产业项目中展现出有影响力的成果；\n4. 熟悉主流深度学习框架、分布式计算框架，能够高效完成复杂模型和数据算法实现与大规模训练优化；\n5. 对前沿AI技术充满热情，具备独立思考、系统研究、复杂问题解决以及良好的协作沟通能力，能够推动研究成果高效落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100016740003","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-技术专家-平台服务-ModelScope魔搭","city":"北京/杭州","category":"技术-基础平台","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100016740003&track_id=SSP1791223737729YaFwtVKPdu5688","duty":"本岗位支持魔搭站点（modelscope.cn）以及整体技术生态对应的后端服务的研发工作。同时负责在快速迭代的AI领域，架接模型贡献者和模型使用者之间的桥梁。支持新模型，新应用的迅速接入，确保前沿模型以及衍生的AI生态能在魔搭上迅速落地。具体工作包括（但不限于）：\n1. 魔搭模型，数据集，创空间等功能研发以及后台服务的管理，以及上层Agentic应用的服务化和产品化建设。\n2. 通过与底层云基座打通，打造魔搭服务平台自动弹性和水平扩展能力，为千万级别的开发者用户提供稳定的服务，实现高效的计算资源使用。\n3. 围绕魔搭的模型生态，开发LLM、Diffusion等各领域大模型实现应用落地所需的相关工具链。并支持模型从ckpt落地为实际应用和服务化所需的自动化部署，评测等一系列工程链路。\n4. 撰写技术设计文档以及用户文档，包括操作手册和最佳实践指南等。","requirements":"职位要求\n1. 硕士及以上学位，计算机科学或相关领域专业。 2年及以上相关领域开发经验。具备大数据平台，机器学习平台，云服务平台，大模型训练推理等领域相关经验者优先。\n2. 扎实的编程能力，精通 Go、Java、Python、C++ 等编程语言。对ModelScope、HuggingFace等开源社区和平台有深入了解和使用经验者优先。\n3. 良好的工程架构设计能力，能够从开发者视角思考问题，能够独立处理复杂的技术挑战。\n4. 出色的分析问题、解决问题能力和团队沟通协调能力。具备较好的英文读写能力。\n5. 对开源社区有技术热情，有开源生态建设相关经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100023780001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-RL算法专家-Qwen","city":"北京/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100023780001&track_id=SSP1791223737729MAijtneCdt3698","duty":"强化学习（RL）是 Qwen 系列基础模型持续演进的重要技术方向，被广泛应用于提升模型在复杂任务中的推理、规划、编码、工具调用与长程决策能力。我们持续探索 RL 在长程代码任务、视觉交互、真实环境执行、数学与代码竞赛等场景中的应用，推动模型在复杂开放任务中的自主性与执行表现。欢迎对大模型与强化学习方向有经验和热情的同学加入。\n工作内容包括：\n1. 研究 PPO、GRPO 等强化学习算法，提升训推分离场景下大规模 RL 训练的稳定性与效率；探索 RL scaling law、长程训练、多任务融合与系统优化等方向，提升模型持续训练收益与泛化能力。\n2. 优化端到端 Agentic RL 链路，提升算法与系统整体效率，增强 agent 在推理、长程规划、代码生成与工具调用等场景中的能力；结合 critic model 与过程奖励机制，对 agent 行为进行有效引导，提升 scaffold 泛化性、指令跟随能力与推理效率。\n3. 提升 RL 在长程任务与复杂开放任务中的表现，研究训练效率优化、复杂任务学习方法；探索多 agent 协作、自我反思、记忆机制与规划等方向，提升奖励信号、奖励模型与agentic verifier的准确性和鲁棒性。\n4. 与研究员和工程师协作，持续迭代coding agent 与long-horizon agent 的训练数据、奖励信号与执行环境；改进合成数据生成方法，针对模型能力短板构建可验证的 RL 数据，提升基础模型在前沿 benchmark 与真实任务场景中的表现。","requirements":"1. 计算机、人工智能、自动化等相关专业本科及以上学历，硕士/博士优先。\n2. 在强化学习（RL）与 Agent 方向具备扎实基础与实际经验，深入理解 PPO、GRPO 等主流 RL 算法及训练方法；有大模型 RL、Agent、代码生成、Reward Modeling 或大规模训练等相关经验者优先；具备复杂任务场景中的算法落地与系统优化经验者优先。\n3. 对真实任务场景与模型行为有较强洞察力，具备目标导向的问题分析与推进能力；对算法、数据与 reward signal 有良好直觉，能够结合实际问题持续迭代方案并提升模型表现。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100018640014","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型平台研发工程师-Agent Infra","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100018640014&track_id=SSP1791223737729BBsxYwocWi7199","duty":"通过技术创新支持阿里集团大模型研发快速迭代，参与从数据生产、训练到评测的大模型研发全流程，主要工作内容和挑战如下：\n1. 建设大规模数据生产和评测的Agent基础设施，增强大模型在Coding&Agentic等领域的能力。\n2. 结合后训练框架，优化强化学习效率，实现高效的大规模Agentic RL。\n3. 将成熟的系统与算法成果发表于学术会议，并回馈开源社区（如ROCK和ROLL等），持续提升在学术界与产业界的影响力。","requirements":"1. 具有良好的编程和工程实现能力，精通Python/Go/Shell等一种或者两种语言。\n2. 有优秀的逻辑和数据分析能力，能够对算法需求进行分析、抽象和设计。\n3. 学习能力较强，愿意学习新东西，具有优秀的分析和解决实际问题的能力和态度，对技术有激情。\n4. 符合以下条件之一者优先：\n   1. 熟悉一种或多种Agent Harness框架者优先， 如OpenCode、OpenClaw等。\n   2. 熟悉有大模型Coding&Agentic方向评测框架者优先。\n   3. 有大模型数据生产和清洗框架者优先。\n   4. 参与过大规模分布式系统的开发、设计和维护优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100006780014","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型平台研发工程师-训练平台","city":"北京/杭州","category":"技术-基础平台","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100006780014&track_id=SSP1791223737729WHphmLNEuk9543","duty":"主要负责 TokenFoundry 大模型训练平台建设，为大模型训练提供稳定、高效、弹性的 AI Infra 基础设施。你将参与新一代大模型训练平台的架构演进，支撑大规模分布式训练任务编排、异构集群资源调度、训练容错与弹性恢复等核心系统，持续提升研发效能与算力利用率。\n主要工作职责和挑战\n1. 训练任务平台设计与研发：负责分布式训练任务的提交、编排、调度、可观测性与全生命周期管理系统的架构设计及核心代码实现。\n2. 大规模资源调度引擎：设计并实现面向异构集群的资源调度策略，涵盖拓扑感知调度、抢占式调度、优先级队列及多租户配额管理等能力。\n3. 平台化与产品化：快速迭代平台产品能力，支撑大模型研发迭代对训练基础设施的能力需求。\n4. 技术攻坚与前沿探索：跟踪 AI Infra 及训练调度领域的最新进展，推动技术方案落地并持续优化系统性能。","requirements":"1. 具备优秀的技术自驱力与分析解决复杂问题的能力，对 AI Infra 技术有强烈热情。\n2. 工程实现能力扎实，精通 Go 或 Java，熟悉 Python；代码规范严谨，重视可测试性与可维护性。\n3. 有平台类产品研发经验，深入理解 Kubernetes 架构与调度机制，具备生产环境 K8s 集群管控及 Operator/Scheduler 开发经验。\n4. 符合以下条件之一者优先：\n    a. 熟悉 Megatron-LM / VeRL / DeepSpeed 等主流分布式训练框架。\n    b. 有大规模 GPU/NPU 异构训练平台的研发经验。\n    c. 追求优雅代码设计，在云原生或 AI Infra 相关开源社区有活跃贡献。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100014000002","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型训练Infra研发工程师-北京/上海/杭州","city":"北京/杭州/上海","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100014000002&track_id=SSP1791223737729YPKorqqBxP9321","duty":"● 负责主流深度学习框架在Token Foundry大模型场景下的工程优化，包括但不局限于MoE模型大规模训练框架、多模态训练框架、RLHF训练框架等，参与包括基模型Pretrain、SFT等多个阶段的训练任务优化；\n● 致力于提升不同阶段模型训练负载的极限吞吐，能够针对不同模型负载系统化的分析不同阶段耗时并提供相应的优化手段，优化手段包括但不局限于算子优化、通信优化、分布式策略优化等；\n● 负责超大规模训练任务的稳定性的设计，通过各种手段来提升训练任务的有效吞吐，构建更可靠的故障检测系统和自愈系统，提供超大规模训练任务的丝滑体验。","requirements":"● 熟悉计算机体系结构基础知识，有扎实异构计算优化(GPGPU/x86/ARM等)、高性能网络架构通信优化、分布式训练策略优化等方面的经验；\n● 扎实的工程能力，优良的编程风格，熟悉Python/C++语言和常用设计模式，具备复杂系统的设计开发调试能力；\n● 熟悉深度学习的基础理论概念，熟悉Transformer架构，熟悉主流大语言模型、多模态模型等模型特点；\n● 熟练PyTorch等领域常用框架，掌握Megatron、DeepSpeed、JAX等不同训练框架的各自特点和细节；\n● 优良的沟通表达能力、团队合作意识和经验；具备快速学习的能力，以及深入钻研技术问题的耐心。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100019400004","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-代码大模型算法工程师-Qwen","city":"北京/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100019400004&track_id=SSP1791223737729ndUzZIcGAz7799","duty":"千问（Qwen）是由Token Foundry自主研发的超大规模语言模型，具备多模态、多语言、跨任务的理解与生成能力。Qwen系列模型，涵盖参数量从亿级到万亿级的基座大语言模型，并相继推出Qwen-VL、Qwen-Audio、Qwen-Omni、Qwen-Coder、Qwen-Image等系列模型。从多轮对话到代码生成，从逻辑推理到内容创作，从单一多模态到全模态统一理解生成，Qwen 正在打造全球领先的全模态模型技术体系，推动AI在企业服务、开发者生态、个人用户等领域的深度应用，引领下一代人工智能的发展。\nCoder 团队致力于构建能够执行、扩展并自我进化的自主系统，通过构建超智能的 coding agent / digital agent，扩展数字世界，为迈向真实世界的智能奠定基础。\n\n工作职责：\n1. 负责通用模型 Qwen 的代码能力和代码专有模型 Qwen-Coder 的构建。\n（1）包括但不限于数据收集、预训练、后训练（强化学习）、评测等方向上的探索。\n（2）我们坚持 Large-scale Pre-training 和 Large-scale RL 来提升 Code Reasoning 能力，在专家级编程竞赛超越人类，并构建 Coding Agent 来解决真实世界软件开发任务。\n2. 负责 Computer-Use Agent (GUI-Agent）的建设，以最直观的方式—鼠标、键盘、编码等操作来代替人类执行数字世界任务。\n（1）通过 Scaling 海量数字世界数据结合大规模合成数据，来提升 Computer-Use Agent 的 Grouding 能力。\n（2）通过 Long Horizon 的方式进行强化训练，结合可扩展的多模态环境反馈来提升 CU Agent 的 Reasoning 的能力。","requirements":"1. 计算机科学、人工智能、机器学习等领域的博士/硕士毕业生。\n2. 对上述前沿问题有持续热情，具备独立思考能力和系统性研究思维，敢于挑战现有范式，能够独立应用技术解决复杂问题。\n3. 在上述方向有过相关的科研或项目经历，在顶级会议上发表过相关论文，有深度学习，大模型等相关经验。\n\n加分项：\n1. 曾发表顶级会议论文并具有一定的学术影响力，包括但不限于：NeurIPS、ICML、ICLR、ACL、TPAMI等国际顶级计算机会议/期刊。\n2. 拥有知名开源项目，在开源社区具有较好的影响力，或在竞赛中获得引领性的研究成果。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100019300008","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-多模态生成算法专家/高级专家-杭州/北京","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100019300008&track_id=SSP1791223737729WLNoxhUkJE4778","duty":"1. 探索研究多模态生成大模型的设计与开发，探究高效生成、生成理解统一、多模态理解、强化学习/RLHF后训练和高效数据管线设计等方向。\n2. 参与研发多模态生成大模型开发等下一代人工智能核心技术，参与大规模生成基础模型预训练与后训练开发。\n3. 负责跟踪和研究多模态生成大模型前沿技术调研、落地、对业务进行优化。","requirements":"1. 计算机科学、人工智能、机器学习或相关领域的硕士或博士学位。\n2. 在扩散模型、自回归模型、多模态生成理解、计算机视觉、NLP、AIGC、计算机图形学、机器学习等一个或多个领域有较深入的研究。\n3. 具有出色的分析、解决问题的能力，能深入解决大模型训练、应用存在的问题，有自主探索解决方案的能力者。\n4. 能够积极创新， 乐于面对挑战， 负责敬业，优秀的团队合作精神，一起探索新技术，推进技术进步。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100028980001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-AI for Engineering 大模型算法专家-Qwen基础模型","city":"北京/深圳/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100028980001&track_id=SSP1791223737729aPxsqWdCHg9360","duty":"推动大模型在芯片设计（EDA）、工业设计（CAD）、工程仿真（CAE）、游戏设计、金融工程、工业自动化、Infra 调优等工程领域的能力演进与落地实践，使模型能够在真实工程生产环境中理解设计规格、调用专业工具、解析反馈信号并持续自进化，通过多轮迭代不断发掘更优算法与设计方案，拓展大模型在工程优化场景中的能力边界。该方向的核心目标是将工程领域的能力训练到主模型中，侧重在不同工程领域间的泛化性，而非构建单一领域的专用系统。\n\n1. Self-Evolving Engineering Agent：研究基于 Self-Evolving、Long-Horizon、Multi-Agent 等 Test-Time Scaling 范式的工程优化能力增强方法，探索 Propose → Execute → Evaluate 迭代循环在多工程领域的统一建模，提升 Qwen 模型在开放工程环境中的泛化性与收敛效率。\n2. Envs & Tool-Chain Integration：构建面向真实工程工具链的 Agent 闭环环境，将专业工具（EDA 编译器/仿真器/综合器、CAD 求解器、物理仿真引擎等）的 CLI 接口与报告输出集成为 Agent 可消费的结构化反馈信号，设计分层 Reward 体系驱动端到端优化。\n3. Domain Data & Training Scaling：挖掘工程领域高价值数据与 workflow（设计规格、工具反馈轨迹、优化历史），构建 General Long-Horizon Data Pipeline；在 CPT → SFT → RL 端到端验证领域适配与训练策略，优化模型在工程任务中的长程推理与迭代优化能力。\n4. Benchmark & Evaluation：跟踪工程智能前沿进展，围绕关键问题开展算法创新、实验分析与技术沉淀；复现并维护高可靠性工程评测环境，建立可量化、可复现的能力评估体系。\n5. AI for Chip Design 加分项：\n（1）EDA Agent Loop：熟悉数字芯片设计全流程（RTL → 综合 → 验证 → 后端），能够将 EDA 工具链集成到 Agent 迭代循环中，构建 \"生成 RTL → 工具验证 → 反馈评估 → 改进设计\" 的闭环优化环境；了解后端 PnR 参数调优、时序收敛、版图优化等迭代流程，能够将布局布线阶段的多维反馈（时序/拥塞/功耗/面积）纳入 Agent 优化循环。\n（2）Verification & Rewarding：具备 Verilog/SystemVerilog 读写能力，能够设计面向 RTL 生成与功能验证的评测体系与训练数据流水线，探索 Agentic 的功能性验证和形式化验证方法。\n（3）AI for EDA Research：关注 AI for EDA 前沿进展，能够将学术界的训练范式落地为可复现的训练方案，在业界评测集上验证并推动芯片设计能力的持续演进；同时关注模拟电路设计、MEMS 及其他非数字电路领域的 AI 落地机会，具备将 Agent 迭代优化范式从数字拓展到模拟、混合信号及微机电系统等方向的研究与落地能力。","requirements":"1. 来自全球Top高校计算机科学、人工智能、电子信息、自动化、集成电路或相关工科领域博士/顶尖硕士毕业生。\n2. 在国际顶级会议/期刊以一作身份发表过多篇高水平论文，或在开源社区、竞赛中展示出引领性的研究成果。\n3. 熟悉主流 Agent 框架与范式，有针对 Agent 特定能力进行模型微调或训练的经验。\n4. 对某一工程领域的生产级落地有丰富knowhow，并在该领域有行业agent的搭建/微调经验。\n5. 熟悉大模型分布式训练框架，有大规模集群上的模型训练与调优经验。\n6. 具备优秀的跨团队协作和沟通能力，能够与工程、产品等团队紧密合作，推动研究成果快速落地并产生实际影响力。\n7. 具备极强的自驱力，敢于挑战现有范式，探索全新模型应用场景和能力边界。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100022900016","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-Computer Use Agent算法专家-Qwen基础模型训练","city":"北京/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100022900016&track_id=SSP1791223737729WqFrNOHpkk9331","duty":"推动 GUI / Hybrid Computer Use Agent 在 Computer / Mobile / Browser 等真实数字环境中的能力演进与落地实践，使模型能够理解、操作并协同完成跨平台、跨界面、跨工具、跨任务流的复杂用户任务，持续提升 Agent 在开放环境中的泛化性、鲁棒性、协同性与实际可用性，拓展大模型在真实人机交互场景中的能力边界。\n1. GUI Agent：重点探索 GUI 在Computer / Mobile / Browse场景下的Agent能力提升与OOD任务能力泛化影响分析，研究大规模自然GUI轨迹Pre-training、用户协同能力；\n2. Hybrid Agent：设计CLI & GUI 统一范式下的Universal Digital Agent Harness & Behavior Pattern，探索用户协同CUA场景下的有效实践方案；\n3. Envs Scaling & Training Scaling：在大规模合成环境和现实环境数据中CPT->RL端到端优化迭代；\n4. Preference & Feedback Modeling：探索用户协同Computer Use场景下用户偏好和用户反馈的收集、建模与处理机制，研究显式反馈与隐式反馈的统一表征方式，建立可用于训练和评估的反馈闭环。","requirements":"1. 来自全球Top高校计算机科学、人工智能、机器学习、深度学习、软件工程或相关领域应届博士/顶尖硕士毕业生；\n2. 在大语言模型或多模态大模型领域有扎实的理论基础和实践经验，在深度学习、大规模模型训练、优化算法、生成式模型、自监督学习等至少一个领域中具有行业影响力的创新性成果；\n3. 在国际顶级计算机会议/期刊以一作身份发表过多篇高水平论文，或在开源社区、竞赛中展示出引领性的研究成果；\n4. 具备扎实的代码功底，熟悉主流深度学习框架，能够高效实现复杂模型结构并进行大规模模型训练（曾参与千卡集群项目者优先）；ACM/ICPC，topcoder等编程比赛获奖者优先；\n5. 对AI技术充满好奇心，持续关注前沿领域，具备独立思考能力和系统性研究思维，敢于挑战现有范式，有志于定义下一代基础模型的进化方向；能够独立应用技术解决复杂问题，主导或深度参与过有行业有影响力项目的人选优先；\n6. 具备优秀的跨团队协作和沟通能力，能够与工程、产品等团队紧密合作，推动研究成果快速落地并产生实际影响力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100029420001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-技术专家-模型工程-ModelScope魔搭","city":"北京/杭州","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100029420001&track_id=SSP1791223737729MTJYaXCStS2410","duty":"本岗位负责围绕ModelScope模型生态，开发各领域模型（尤其是LLM，多模态理解以及Diffusion生成等）落地所需的相关开源工具链。探索强化学习、模型评估、Agent系统、持续学习等前沿技术，并支持相关技术的通过魔搭站点以及生态为依托，实现服务化落地。打通模型从ckpt落地为实际应用所需的自动化部署，评测等一系列工程链路，以及Agentic应用生态的落地。同时参与跨部门、跨公司、以及与全球开源社区的协作，探索AI领域前沿技术研究与创新，推动包括大模型在内的各领域最前沿模型生态的发展和推广。","requirements":"1. 硕士及以上学位，计算机科学或相关领域专业。 2年及以上相关领域开发经验。对LLM、Diffusion等模型等，以及围绕模型的工具框架体系，以及AI Infra方向有深入了解。在大模型的训练微调、评估、Agentic生态等领域研发经验者优先；具备大模型训练微调（SFT，RL等）经验，对Megatron，transformers，flashattention以及vLLM/Sglang等框架有相关开发经验者优先。\n2. 扎实的编程能力，精通 Python、Rust等编程语言。对ModelScope、HuggingFace等开源社区和平台有深入了解和使用经验者优先。\n3. 良好的工程架构设计能力，能够从开发者视角思考问题，能够独立处理复杂的技术挑战。\n4. 出色的分析问题、解决问题能力和团队沟通协调能力。具备较好的英文读写能力。\n5. 对开源社区有技术热情，有开源生态建设相关经验者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100013020011","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-AI For Science算法专家/高级算法工程师-北京","city":"北京","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100013020011&track_id=SSP1791223738058mXGcrCcMKh6392","duty":"1、负责AI for Science尤其是生物医药方向的基础算法的研究和研发落地，包括不限于蛋白语言模型，基因语言模型，分子基础模型，生成式生物模型等。\n2、对AI for Science尤其是基因全链路分析，药物早筛等问题中涉及的智能化和生成式模型等技术进行快速试错，找到可行方案，并不断对其进行创新改进，在各项性能指标上超出现有方案，不断提升行业天花板，不断完善相应的服务化工具。\n3、以人工智能技术和高性能计算为基础，在相关方向产出高水平的文章，专利和软件服务，完善公司在AI for Science方面的技术布局，提升公司在相关领域的影响力。","requirements":"1、计算机、人工智能等相关专业博士学历，有一定的生物学背景知识，或有强烈的学习兴趣。\n2、具备扎实的算法基础和算法实现能力，熟练掌握任一深度学习框架，如pytorch/tensorflow/JAX等。\n3、对前沿算法问题有突破创新能力，并具备在相关领域产出高水平研究成果的能力，发表过相关的高水平论文者优先，如CCF-A类会议，CNS以及子刊等。\n4、具备良好的沟通协作能力和跨团队合作意识，能够灵活运用多种方法来解决实际问题。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100013120010","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大语言模型算法专家/高级算法工程师-杭州","city":"杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100013120010&track_id=SSP1791223738058IOQBzelkaZ9754","duty":"1. 高质量垂域数据工程：深入优化垂直领域（如文本内容审核）的高质量数据构建与迭代方法论，持续提升数据的质量、多样性与生产效率。\n2. 可扩展后训练体系：探索适配领域特性的 SFT/RL 算法，构建高效、稳定、可扩展的垂域模型后训练范式，系统性提升模型能力。\n3. 前沿技术研究与落地：探索推理模型前沿技术（如高效蒸馏、reward system、agentic RL、test-time learning 等）以及模型可解释性技术，沉淀技术成果和影响力，并推动大模型相关技术在行业场景中的转化与落地，提升领域模型竞争力，支撑业务持续增长。","requirements":"1. 具备扎实的大语言模型post-training实践经验(SFT/RL/Agent等)和垂域大模型研发落地经历；所研发模型具备大规模线上应用经历(如日均调用量达千万及以上)者优先。\n2. 精通Python等语言，熟练掌握PyTorch、verl、vllm等主流训练和推理框架，具备扎实的coding能力；在ACM-ICPC等国内外知名算法竞赛中取得优异成绩者优先。\n3. 能够独立主导从问题建模、数据治理、算法任务设计、实验验证等完整技术闭环；作为核心贡献者参与过高影响力的开源项目或发表过有高影响力的技术报告，高质量论文(NeurIPS、ICLR、ICML、ACL等)者优先。 \n4. 对解决复杂技术问题、探索post-training前沿技术具备强烈的自驱力和技术热情；有较强的业务理解能力，具备良好的沟通协作能力和跨团队合作意识，能够高效推动项目落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100034360001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-AI智能手机全栈算法工程师-Memory / Agent / 多模态方向","city":"北京/杭州/上海","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100034360001&track_id=SSP1791223738058ZXJFXJnhmw6851","duty":"我们正在建设面向下一代AI智能手机的核心算法团队。团队重点关注大模型在智能终端上的理解、推理、感知与任务执行能力，研究方向包括个人记忆（Memory）、智能体（Agent）、端侧多模态感知、端侧模型及端云协同等。\n你将参与从前沿研究、数据构建、模型训练，到系统实现、评测验证和产品交付的完整研发过程，探索下一代AI智能手机的核心能力。我们希望你兼具扎实的算法能力和优秀的工程能力，具备AI手机或智能终端研发经验，能够将前沿算法转化为稳定、高效、可规模化交付的产品能力，并与ToB建设团队共同推动技术落地。\n岗位职责\n1. 参与AI手机个人记忆与个性化智能的算法及系统研发，重点提升个人信息的理解、组织、检索和更新能力，推动Memory与Agent、个人搜索等能力结合。\n2. 参与端侧多模态感知模型的研发与优化，提升手机对图像、语音、视频、文本及设备上下文的理解能力，并在效果、延迟、内存和功耗之间取得平衡。\n3. 参与Agent核心算法及端云协同能力建设，持续提升模型的任务规划、工具使用、记忆调用和复杂任务执行能力。\n4. 参与算法的端到端工程实现，建设数据、训练、推理和评测关键链路，解决模型效果与系统性能问题，推动算法从研究原型走向产品级交付。\n5. 与产品、工程及ToB建设团队协作，将业务需求转化为明确的算法问题和评测目标，推动方案验证、集成交付和持续迭代。","requirements":"任职要求\n1. 计算机、人工智能等相关专业，硕士或博士学历。\n2. 具备1年以上大模型或智能终端算法研发经验，具有AI手机或智能终端算法工程经验。\n3. 在以下至少一个方向具备深入积累：\n    ○ 个人记忆、Personal RAG、个人搜索或用户建模；\n    ○ Agent、任务规划、工具使用或Agent后训练；\n    ○ 端侧视觉、语音、视频理解或多模态感知；\n    ○ 端侧模型、模型压缩、推理加速或端云协同。\n4. 具备扎实的机器学习和深度学习基础，深入理解Transformer、大语言模型和多模态模型，并具有模型训练或后训练实践经验。\n5. 具备端侧模型研发经验，熟悉模型压缩和推理优化方法，能够针对移动设备约束优化模型效果、延迟、内存和功耗。\n6. 熟悉主流模型训练框架及至少一种端侧或服务端推理技术栈，具备模型训练、部署和评测的实际经验。\n7. 具备较强的技术判断力和Owner意识，能够解决开放性问题，并持续推动结果落地。\n加分项\n1. 主导/参与过已经规模化落地的AI手机、个人智能、Memory、Agent或端侧多模态项目，并对核心业务指标或用户体验产生可量化的提升。\n2. 具备端云协同算法架构经验，能够根据任务复杂度、设备资源、网络状态、隐私要求和服务成本进行模型路由及系统优化。\n3. 具备优秀的沟通表达和跨团队协作能力，能够面向算法、工程、产品、解决方案及客户团队，清晰说明技术原理、方案取舍、评测结果、能力边界和业务价值。\n4. 具备ToB业务、企业级AI、客户项目或联合交付经验，能够参与需求澄清、方案设计、技术评审、指标定义、交付验收和问题复盘。\n5. 具备大规模向量检索、知识图谱、长上下文、持续学习、模型服务或分布式训练推理经验。\n6. 在Apple、Google、国内头部手机厂商、知名大模型团队、研究机构或相关智能终端团队有工作经历。\n7. 在NeurIPS、ICML、ICLR、ACL、EMNLP、CVPR、ICCV、ECCV、AAAI等高水平会议或期刊发表过相关论文，或参与过有影响力的开源项目。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100007800001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-云端推理服务技术专家-北京/杭州","city":"北京/杭州","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100007800001&track_id=SSP1791223738058PTmuaXdkjD9635","duty":"1.  设计并构建面向多模态交互（语音、视觉、语言、上下文融合）的云端推理服务平台，支持Omni/Speech/VL等大模型的在线/近线推理。\n2.  主导端云协同架构中云端服务模块的技术方案，包括模型服务化（Model Serving）、动态批处理（Dynamic Batching）、请求调度、弹性扩缩容、负载均衡等关键能力。\n3.  优化云端推理链路的延迟、吞吐与资源利用率，针对ToB客户对SLA（如99.9% 构建统一的服务治理框架，集成监控告警、日志追踪（如OpenTelemetry）、AB测试、灰度发布、故障自愈等运维能力。\n4.  与算法团队紧密协作，推动模型结构适配、量化部署、缓存策略等端云联合优化方案落地。","requirements":"1.  计算机科学、软件工程或相关专业硕士及以上学历，3年以上后端/云服务/推理平台开发经验。\n2.  精通Go/Python/C++至少一种语言，具备扎实的系统编程和高并发服务开发能力。\n3.  熟悉主流推理框架（如Triton Inference Server、vLLM、TensorRT-LLM、ONNX Runtime）及模型服务化最佳实践。\n4.  有大规模AI服务部署经验，熟悉GPU资源调度、模型版本管理、冷启动优化、长尾请求处理等典型问题。\n5.  有ToB项目交付经验，能理解客户需求并转化为可靠、可运维的技术方案。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:7000043416","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-模型训练/推理优化算法专家-万相Wan","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=7000043416&track_id=SSP1791223738058QviBFdlgSN9603","duty":"【部门介绍】\n随着大模型技术的飞速发展，理解和生成多模态数据（图像、视频、音频、3D素材等）的能力日益增强。目前，构建能够同时进行输入和输出的多模态世界模型已成为业界的研究热点，也是实现通用人工智能（AGI）的重要技术路径之一。\n万相Wan将持续在世界模型、原生多模态预训练、理解-生成融合范式、统一Tokenizer研究、人类反馈与强化学习等前沿技术方向上进行探索，始终追求在多模态世界模型领域的领先研究地位，致力于建立世界级的技术影响力。\n\n【职位描述】\n1. 负责万相Wan多模态生成大模型研发，重点解决生成大模型的训练和推理效率问题。\n2. 负责研发各种蒸馏加速算法，包括CFG蒸馏，推理步数蒸馏等。\n3. 负责研发各种Training-free推理加速算法，不限于cache、量化、采样优化等策略。\n4. 负责研发生成模型的高效训练架构，包括但不限于sparse/linear attention、时空独立建模、超分模块等策略。","requirements":"1. 计算机科学、人工智能、机器学习能等领域的博士/硕士毕业生，掌握机器学习和深度学习基础知识，熟悉常用视觉生成算法，熟悉Pytorch、Tensorflow等至少一种深度学习框架。\n2. 极佳的工程实现能力，熟练掌握C/C++、Java、Python等至少一门语言 ，ACM/ICPC、topcoder等编程比赛获奖者优先。\n3. 良好的科研能力，有成果发表在CVPR、ICCV、NeurIPS、ICLR、TPAMI等国际顶级会议、期刊者优先。\n4. 对生成方向具有技术热情、良好的技术洞察力和优秀的业务分析能力，能应对复杂的业务算法需求。\n5. 关注技术影响力，具有开源开放精神，对基础模型的前沿问题有持续热情，有追求，渴望做出有极大影响力的工作。\n6. 具备跨学科视野与协作意识，能够与工程、产品等多学科团队紧密合作，推动研究成果快速落地并产生实际影响。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100039300001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-AI高级产品运营（音乐模型方向）-未来生活实验室","city":"北京/杭州","category":"运营-产品运营","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100039300001&track_id=SSP1791223738058uvooiQwowq7045","duty":"1、负责 HappyShrimp音乐模型产品运营工作，深入理解用户需求及音乐创作场景，围绕产品核心链路、功能体验、用户反馈等持续推动产品优化和运营策略落地。\n2、具备专业音乐判断能力，能够与产品、算法及评测团队协同，从用户和音乐专业视角共同定义“什么是好的 AI 音乐”，并将音乐审美、用户需求转化为产品及模型优化方向。\n3、负责 AI 音乐产品的用户增长和运营活动策划，围绕拉新、激活、留存、创作转化等目标，持续探索适合 AI 音乐产品的增长机制、内容玩法和运营策略。\n4、负责重点版本、新能力及产品节点的营销策划，提炼产品核心卖点，联合品牌、市场、内容等团队策划具有传播力和用户参与感的营销项目。\n5、负责头部达人、音乐人及创作者合作，持续拓展优质合作资源，策划联合创作、内容共创、产品体验及传播项目，打造具有影响力的 AI 音乐标杆案例。","requirements":"1、5 年及以上音乐产品运营或相关经验，有较强的独立项目负责和跨团队推动能力；\n2、具备扎实的音乐乐理基础和音乐审美，能够专业理解作曲、编曲、旋律、和声、演唱及不同音乐风格；\n3、具备互联网音乐行业工作经验，熟悉音乐流媒体、音乐创作工具、音乐社区、音乐人生态或数字音乐行业；\n4、具备较强的产品思维和用户洞察能力，能够理解复杂产品逻辑，并将用户及音乐专业需求转化为产品运营策略；\n5、有音乐类用户增长、内容营销或产品营销经验，能够独立策划并推动大型运营或营销项目落地；\n6、有音乐人、头部达人、创作者或内容生态合作经验，对年轻用户、社交媒体及音乐内容趋势有较强敏感度；\n7、对生成式 AI 和 AI 音乐有较强兴趣，熟悉国内外主流 AI 音乐产品及行业发展趋势。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100034660005","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-业务HRG专家/高级业务HRG专家-AI大模型方向","city":"杭州","category":"综合类-人力资源","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100034660005&track_id=SSP1791223738058oDFtvSTUEY9118","duty":"我们希望你深入大模型业务，作为业务Leader的组织与人才伙伴，围绕AI大模型业务战略，推动组织能力建设、关键人才供给与保留、文化机制建设及数据化运营，以组织效能支撑业务目标实现。\n\n1、战略落地与组织设计：深入理解业务战略，推动目标拆解、落地、阶段性复盘与调整；结合行业趋势、竞对动态及组织发展阶段，设计并推动适配的组织策略。\n2、人才供给与发展：制定岗位与人才标准，持续提升人才密度；推动关键产研人才，尤其是AI大模型领域人才的即时供给与保留，促进人才结构持续优化。\n3、组织文化与机制建设：以身作则践行文化价值观，增强团队归属感与凝聚力；围绕业务场景建设沟通、决策和复盘机制，完善激励与约束体系，激发组织活力；妥善处理员工事件与合规事项，营造积极正向的组织氛围。\n4、数据驱动与效能提升：通过数据看板和数字化工具识别组织问题，形成高质量洞察并推动解决；推动数据系统产品化建设，帮助业务减负降本。","requirements":"1、8年以上工作经验，其中5年以上HRBP/HRG经验。\n2、具备研发、算法等技术团队的HRBP/HRG经验，对AI/大模型等技术方向有一定认知，理解技术团队的工作方式及人才特点。\n3、精通人才盘点、组织诊断、机制设计等专业方法，能够识别关键问题并推动解决方案落地。\n4、能够与业务Leader就组织策略开展高质量对话，预判关键问题，并独立形成系统性解决方案。\n5、具备强烈的好奇心和学习敏锐度，主动拥抱新事物、新趋势，愿意打破惯性；对AI有真正的好奇与一定理解。\n6、眼中有事、心中有人，既围绕战略目标开展工作，也关注组织中的人；具备良好的沟通能力，能够快速建立信任与连接。\n7、具备较强的韧性和抗压能力，能够适应不确定性与挑战。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100035520001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型平台研发工程师-测试开发","city":"北京/杭州","category":"技术类-质量保证","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100035520001&track_id=SSP1791223738058CfoeNEPAfA8993","duty":"主要负责 TokenFoundry 大模型平台建设，为大模型训练提供稳定、高效、弹性的 AI Infra 基础设施。\n\n\n1. 负责Token Foundry数据生产、训练和评测平台质量保障体系建设，支持大模型平台研发快速迭代；\n2. 制定和推进测试策略、测试计划和测试方法，进行缺陷跟踪和软件质量分析等工作；\n3. 借助Agent / Skill能力，提升测试效率、质量和覆盖范围；研究 LLM 在测试领域的应用，推动技术创新落地。","requirements":"1. 3 年以上测试或质量保障经验，有 AI/大模型产品经验者优先；\n2. 精通Python/Java/Shell等一种或者两种语言，具备扎实的工程化能力和系统设计能力；\n3. 能够从业务视角定义质量问题并推动解决；较强的责任心，具备良好的问题定位能力与跨团队协作能力；对技术有激情，喜欢钻研，能够结合技术发展提出创新想法并落地。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100035480001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型平台产品经理-训练平台","city":"北京/杭州","category":"产品类-平台型","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100035480001&track_id=SSP1791223738058KdyWwcFGNu3050","duty":"负责Token Foundry大模型训练平台的产品规划与建设。深入算法训练场景，整合底层基础资源，提升训练任务的运行效率、稳定性和资源使用效率。\n\n\n1. 负责大模型训练平台的产品规划与迭代，制定产品方案和版本计划，并对交付结果负责。\n2. 深入大模型训练过程，识别任务运行、资源使用和研发效率等方面的问题，形成可落地的产品方案。\n3. 将不同算法团队的训练需求抽象为标准化、可复用的平台能力，推动平台规模化服务算法研发。\n4. 协同算法、研发及基础设施团队，协调资源并推动项目落地。","requirements":"1. 2年以上工作经验，有机器学习平台、AI研发平台产品相关工作经验优先。\n2. 熟悉大模型训练流程，理解分布式训练、训练性能、任务稳定性及底层资源之间的基本关系。\n3. 具备复杂技术场景下的需求理解、抽象和系统方案设计能力，能够将算法需求转化为通用平台方案。\n4. 具备优秀的沟通协同和项目管理能力，自驱力强，能够推动复杂项目取得结果。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100015400002","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-模型研发项目经理-北京/杭州","city":"北京/杭州","category":"技术类-综合","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100015400002&track_id=SSP1791223738058BPlxEAAxAo9406","duty":"1、负责项目的前期规划、需求分析、技术方案设计、资源协同与调配等工作。\n2、负责项目进度把控、质量保障、风险管理及问题整改工作。\n3、对所负责项目进行有效成本控制，确保目标达成。\n4、负责团队人员的管理，提升团队整体能力，提升项目质量。\n5、负责项目过程中的沟通协调，解决复杂问题。","requirements":"1、具备扎实的专业知识基础，有丰富的软件研发或系统架构经验，精通项目管理知识，并能熟练运用到工作中。\n2、3年以上项目管理相关工作经验，具备PMP证书优先。\n3、具有良好的沟通能力和组织协调能力，能够承担较大的压力。\n4、具备较强的逻辑思维能力和创新意识，能够适应快速变化的环境和工作。\n5、熟悉大型企业信息化系统的建设。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100007640008","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-AI交互模型算法专家-北京/杭州","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100007640008&track_id=SSP1791223738400kkZDWgxgWh6878","duty":"1.  负责面向AI手机等ToB场景的多模态交互模型研发，包括语音基础模型、视觉-语言模型（VLM）、全模态大模型的后训练（CPT/SFT/RL）与推理优化。\n2.  研发基于神经网络、扩散模型或大模型的端侧音频信号处理算法（如语音增强、降噪、去混响），提升复杂声学环境下的语音交互质量。\n3.  构建支持自然打断、精准判停、上下文感知的实时双工交互模型，实现低延迟、高鲁棒性的流式对话体验。 \n4.  针对端侧资源约束，开展模型压缩、量化、蒸馏及高效部署，确保算法在DSP/NPU等嵌入式平台稳定运行。 \n5.  与系统、产品团队紧密协作，推动算法从原型验证到大规模商用落地。","requirements":"1. 计算机、人工智能、电子工程等相关专业硕士及以上学历，3年以上AI模型或音频算法研发经验。\n2.  在以下至少两个方向有扎实实践： \n①基于神经网络/Diffusion/LLM的语音信号处理（增强、降噪、语音修复等） ；\n②语音大模型、视觉-语言模型（VLM）或全模态（Omni）大模型的后训练（CPT/SFT/RL） ；\n③双工交互核心技术：VAD、打断检测（Barge-in）、语义判停、流式响应。\n3.  熟练掌握PyTorch，具备大模型训练、调优及端侧部署经验。\n4.  有AI手机、IoT等智能终端项目落地经验，熟悉ARM/DSP/NPU架构者加分。 \n5.  具备良好的工程能力、产品意识和跨团队协作精神，能平衡性能、延迟与功耗。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:7000042531","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-多模态世界模型前沿技术研究-万相Wan","city":"北京/杭州","category":"","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=7000042531&track_id=SSP1791223738400tLmwyizMWl6425","duty":"【部门介绍】\n随着大模型技术的飞速发展，理解和生成多模态数据（图像、视频、音频、3D素材等）的能力日益增强。目前，构建能够同时进行输入和输出的多模态世界模型已成为业界的研究热点，也是实现通用人工智能（AGI）的重要技术路径之一。\n万相Wan将持续在世界模型、原生多模态预训练、理解-生成融合范式、统一Tokenizer研究、人类反馈与强化学习等前沿技术方向上进行探索，始终追求在多模态世界模型领域的领先研究地位，致力于建立世界级的技术影响力。\n\n【工作内容】\n1. 探索大规模多模态理解生成统一基础模型，包括但不限于：统一建模设计、高效模型结构设计、高效Scaling、视觉Tokenizer、多模态联合训练等。\n2. 探索和突破多模态强化学习，包括但不限于：视觉CoT、面向复杂视觉设计任务的强化学习设计、基于用户反馈的在线自学习等。\n3. 构建基于生成模型的真实世界渲染引擎，探索新的多模态交互范式，探索虚拟和真实世界的强化反馈链路设计。","requirements":"1. 计算机科学、人工智能、机器学习能等领域的博士/硕士毕业生。\n2. 在国际顶级计算机会议/期刊（如NeurIPS、CVPR、ICLR、ECCV、TPAMI等）以一作身份发表过多篇论文，或在开源社区、竞赛中展示出引领性的研究成果。\n3. 具备扎实的代码功底，熟悉PyTorch/TensorFlow等框架，能够高效实现复杂模型结构并进行大规模训练经验；ACM/ICPC，topcoder等编程比赛获奖者优先。\n4. 关注技术影响力，具有开源开放精神，对基础模型的前沿问题有持续热情，有追求，渴望做出有极大影响力的工作。\n5. 具备跨学科视野与协作意识，能够与工程、产品等多学科团队紧密合作，推动研究成果快速落地并产生实际影响。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:7000043117","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-多模态生成模型算法专家-万相Wan","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=7000043117&track_id=SSP1791223738400KoxiHDVJQl6434","duty":"【部门介绍】\n随着大模型技术的飞速发展，理解和生成多模态数据（图像、视频、音频、3D素材等）的能力日益增强。目前，构建能够同时进行输入和输出的多模态世界模型已成为业界的研究热点，也是实现通用人工智能（AGI）的重要技术路径之一。\n万相Wan将持续在世界模型、原生多模态预训练、理解-生成融合范式、统一Tokenizer研究、人类反馈与强化学习等前沿技术方向上进行探索，始终追求在多模态世界模型领域的领先研究地位，致力于建立世界级的技术影响力。\n\n【工作内容】\n1、负责原生多模态模型研究和开发，结合多模态能力（支持文本、图像、语音输入）实现复杂指令生成，包括但不限于文生图、图生图、文档生成、可控编辑等核心方向。\n2、负责图像生成模型效果优化，探索扩散模型、自回归模型结构和策略优化等核心技术课题。\n3、负责人类反馈与强化学习，聚焦于更加精细的RL算法设计，并基于万相用户反馈的RLHF图像生成质量提升。","requirements":"1. 计算机科学、人工智能、机器学习能等领域的博士/硕士毕业生，具备计算机视觉等领域的扎实理论基础。\n2. 掌握机器学习和深度学习基础知识，熟悉常用视觉生成算法，熟悉Pytorch、Tensorflow等至少一种深度学习框架。\n3. 具备良好的科研能力，有大规模视觉生成算法相关研究经历和具有影响力科研工作（高引论文、知名开源项目等）者优先，有成果发表在CVPR、ICCV、NeurIPS、ICLR、TPAMI等国际顶级会议、期刊者优先。\n4. 对生成方向具有技术热情，具备视觉生成大模型研发经验，有对话系统、多模态生成等落地项目经验者优先。\n5. 具备良好的技术洞察力和优秀的业务分析能力，能应对复杂的业务算法需求，能够与工程、产品等多学科团队紧密合作，推动研究成果快速落地并产生实际影响。\n6. 关注技术影响力，具有开源开放精神，对基础模型的前沿问题有持续热情，有追求，渴望做出有极大影响力的工作。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100022860013","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-合版算法专家-Qwen","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100022860013&track_id=SSP1791223738400eHNRhDfXGe5785","duty":"1. 合版核心算法研究：探索 On-policy Distillation、知识融合等先进技术，研究更优的 SFT Objective，实现多能力模型的高效合版，最大程度减少能力冲突与遗忘。\n2. 数据策略与冲突消解：深入分析不同能力域的数据配比，建立系统化的冲突检测与消解机制，制定科学的合版数据策略，保障模型在各项能力上的均衡与稳定。\n3. 合版评测体系建设：设计并推进高效、快速的合版评测方案，构建覆盖多维能力的自动化评测 Pipeline，实现合版效果的快速迭代与精准度量。\n4. 合版链路自动化：推动合版全流程的工程化与自动化，包括训练、评测、对比分析、版本管理等环节，提升模型交付的效率与可靠性。\n5. 前沿技术追踪与落地：持续关注模型融合、蒸馏、多任务学习等领域的前沿进展，将有效方法快速验证并落地到Qwen的合版实践中。","requirements":"1. 计算机、机器学习、人工智能等相关专业，硕士及以上学历，博士优先。\n2. 具有大模型 Post-training（SFT / RL 等）或模型蒸馏、模型融合相关方向的实践经验。\n3. 精通 Python 及 PyTorch 等深度学习框架，具备扎实的工程实现能力，能够独立完成从算法研究到工程落地的全链路工作。\n4. 对数据敏感，具备良好的数据分析能力，能够系统性地定位模型能力瓶颈并制定优化策略。\n\n加分项\n1. 熟悉 LLM 训练框架（如 Megatron-LM、DeepSpeed、FSDP）及推理引擎（如 vLLM、SGLang）的实现原理。\n2. 曾在 NeurIPS、ICLR、ICML、ACL 等顶级会议发表论文，在模型融合、知识蒸馏、多任务学习等方向具有一定学术影响力。\n3. 拥有知名开源项目贡献经历，在开源社区具有较好的影响力。\n4. 有大规模模型交付或版本迭代管理经验，熟悉模型从训练到上线的完整生命周期。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100033660009","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-创作者生态运营-Qwen image","city":"北京/杭州","category":"运营类-内容运营","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100033660009&track_id=SSP1791223738400kgfDHJDwHp1913","duty":"1、负责 Qwen-Image创作者生态的搭建与长期运营，拓展和维护国内外优质创作者；策划并落地创作者招募、成长及分层运营机制，提升核心创作者活跃度与内容产出；结合模型能力及重点节点，推动创作者生产高质量案例及内容\n2、负责 Qwen-Image 相关社区、社群的日常运营与用户维护，建立稳定、高质量的用户社区；探索海外社区运营及本地化生态建设\n3、负责包括「Qwen-Image 大使」在内的长期创作者项目，从招募、筛选、资源扶持到效果评估进行完整运营；协调 Token、API、模型体验等资源，为重点创作者提供针对性支持\n4、深入了解创作者使用场景及真实需求，持续收集模型体验、产品功能及内容创作反馈；并对反馈进行结构化分析，与产品、算法团队协同，推动重点问题解决及模型体验优化","requirements":"1、3 年及以上互联网社区运营、创作者运营或用户运营相关经验，有成熟项目独立负责经验\n2、熟悉国内外主流社交媒体、创作者平台及社区生态（discord、github、youtube、X、reddit等），对 AI 创作领域有较高敏感度\n3、熟悉Qwen-Image、Midjourney、Stable Diffusion、FLUX、nano-banaba、seedream等 AI 图像产品，有 AI 内容创作经验者优先\n4、具备良好的跨团队协作能力，能够与产品、算法、市场等团队高效配合推动项目落地\n5、具备较强的数据分析意识，能够结合用户反馈和运营数据进行问题判断与策略优化\n6、英语可作为工作语言（雅思7以上优先），有海外社区、海外创作者或全球化产品运营经验者优先","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100009140003","sourceKey":"tongyi_social","company":"通义","title":"Token Foundary事业部-AI高级海外运营-Happy Horse","city":"北京/杭州","category":"运营类-内容运营","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100009140003&track_id=SSP1791223738400HMIJftpdqz6252","duty":"1、负责HappyHorse海外内容+用户运营体系，包括 Discord、Instagram、TikTok、X、YouTube 等平台，持续提升模型的影响力、社区活跃度及用户增长\n2、负责构建全球AI创作者生态，建立并运营海外创作者及达人合作体系、Affiliate分销体系及品牌共创，持续扩大模型在海外创作者生态中的影响力\n3、与增长团队协同，持续探索海外高质量增长渠道，制定不同渠道的内容策略与素材方案，通过数据分析不断优化投放效果\n4、持续跟踪全球AI行业及内容平台最新趋势，探索海外AI 社区及新兴增长渠道，推动创新合作模式及品牌传播\n5、深度洞察海外用户需求，结合社区反馈、达人反馈及行业趋势，与产品团队共同推动产品体验持续优化","requirements":"1、本科及以上学历，5年以上年海外运营经验，有AI 产品或创作者平台经验优先\n2、熟悉海外主流社交媒体及社区生态，包括Discord、Instagram、TikTok、X、Reddit、YouTube 等，对海外内容传播机制及用户生态有深入理解\n3、有海外达人合作、Creator Economy、Affiliate、内容营销等相关经验者优先，有成功打造海外爆款案例者优先\n4、对生成式AI保持高度关注，熟悉AI 图片、视频、音乐等相关产品，对全球AI 行业发展趋势有持续研究和判断\n5、英文可作为工作语言，具备良好的跨团队协作能力，能够独立负责跨部门项目落地\n6、具备优秀的内容策划能力及数据分析能力，能够基于不同渠道制定运营策略","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100029680001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型训练Infra工程师-训练稳定性方向","city":"北京/杭州","category":"技术类-开发","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100029680001&track_id=SSP1791223738400oMhjBbdobI8381","duty":"1. 建设超大规模训练的稳定性治理体系，围绕有效训练时长（ETTR）与 Goodput 做端到端度量与优化，量化并持续压缩因故障、回滚、启动带来的无效算力（Badput）。\n2. 构建覆盖软硬件异常的故障可观测能力，完善日志、指标、事件的采集与关联分析；研发智能诊断能力，实现训练 slow / hang / OOM / 通信异常等故障的快速定界与根因追溯，沉淀故障模式库与自动诊断规则。\n3. 研发自动容错与快速恢复机制，支持断点续训、Pod 级快速重启、节点自动自愈、动态降级与局部重试；优化 failover、本地盘 / 缓存与 Checkpoint 恢复链路，缩短故障恢复时延。\n4. 建设节点健康度评估与主动巡检体系，覆盖 GPU、网络、存储等软硬件健康，实现故障节点的快速隔离与自愈；支持 Ray 等分布式框架下的作业级故障感知与处理。\n5. 与算法及框架团队协同保障训练全生命周期稳定交付，沉淀可复用的稳定性平台能力，推动变更灰度与自动化运维。","requirements":"1. 计算机、电子、自动化等相关专业本科及以上学历，2 年以上分布式系统或大规模基础设施研发经验。\n2. 扎实的分布式系统与 Linux 基础，熟悉常用性能与故障诊断工具（nvidia-smi、nsight、perf、py-spy、gdb、strace 等），有较强的疑难问题定位能力。\n3. 具备以下至少一个方向的深度实践经验：\n\ta. 大规模分布式作业的容错与自愈系统（故障检测、断点续训、快速重启、failover、Checkpoint 恢复优化，类比 DLRover 等开源项目）；\n\tb. 大规模系统可观测与智能诊断（日志 / 指标 / 事件关联分析、根因定位、异常检测）；\n\tc. 节点健康度评估、硬件故障诊断或 SRE / 稳定性工程体系建设。\n4. 了解大模型训练 / RL 的基本流程与常见故障模式（slow、hang、OOM、NCCL 通信异常等），了解 PyTorch、Ray 等框架的运行机制；具备良好的问题抽象与系统设计能力。\n5. 良好的工程素养与跨团队协作能力，能在高强度、快迭代的大模型训练场景中稳定交付。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100011240014","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型预训练算法工程师-Qwen","city":"北京/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100011240014&track_id=SSP1791223738400WjfKyIiLTB1974","duty":"1. 预训练数据：大规模预训练数据合成技术探索、STEM & reasoning 优化、长尾知识优化、精品数据挖掘过滤、自然数据 scaling、长文本优化、面向 test-time scaling 的数据优化。\n2. 预训练策略：新型预训练损失函数探索、遗忘对抗与持续学习、optimizer 优化、lr scheduler 优化、课程学习、scaling law 预测、超参优化。\n3. 模型结构：新型模型结构探索、模型可解释性、MoE 优化、参数扩展与裁剪蒸馏、线性注意力、动态稀疏注意力、draft model 优化、动态计算优化、KV cache压缩、长序列优化、decoding 加速等。","requirements":"1. 计算机科学、人工智能、机器学习能等领域的博士/硕士毕业生。\n2. 对上述研究方向的某一项或者几项有完整的研究经历或者实际的工业界落地经验。\n3. 关注技术影响力，具有开源开放精神，对基础模型的前沿问题有持续热情，有追求，务实，渴望做出有极大影响力的工作。\n4. 具备独立思考能力和系统性研究思维，具备较强的动手能力，敢于挑战现有范式，能够独立应用技术解决复杂问题。\n\n加分项：\n1. 对LLM的训练优化或推理有深入认知，熟悉 Triton 或 CUDA；\n2. 曾发表顶级会议论文并具有一定的学术影响力，包括但不限于：NeurIPS、ICML、ICLR、ACL、TPAMI等国际顶级计算机会议/期刊。\n3. 拥有知名开源项目，在开源社区具有较好的影响力，或在竞赛中获得引领性的研究成果。\n4. 具有大规模预训练实战经验。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100013560003","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-基础大模型 Post-Training 算法专家-杭州/北京","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100013560003&track_id=SSP1791223738400UxpRmDZQXD6584","duty":"1. 负责大模型 Post-Training 全链路算法建设，覆盖 Pre-SFT、SFT、RLHF、RLVR（PPO / DPO / GRPO 等）各阶段的算法调优与策略设计，提升模型在指令遵循、工具调用、安全合规、多轮交互、long horizon task 等核心维度的综合能力。\n2. 负责 Reward Model 的设计、训练与迭代优化，构建 Verifier、LLM as Judge、Rule 等多元 Reward System，优化多维度（安全性、准确性、有用性、逻辑性、拟人度等）的偏好数据采集策略与训练方案。\n3. 设计高质量 SFT / RL 数据采集、清洗与标注方案，建立数据质量评估标准；通过实验驱动数据配比方法论，探索高质量数据合成、Agentic RL 等前沿方法，持续提升数据质量与多样性。\n4. 参与模型合版工作，包括数据配比策略、多任务训练优化、灾难性遗忘缓解等核心技术，确保各业务线智能体能力与基座模型的高效融合；分析线上 Badcase，将 RL 信号融入模型训练全流程。\n5. 探索 LLM 及 VLM 场景下的 Post-Training 方案，解决跨模态对齐与幻觉问题；跟踪 Agentic RL 等前沿研究进展，推动技术创新在基座大模型及 APP 对话助手产品中的落地。","requirements":"1. 计算机科学、人工智能、数学等相关专业硕士及以上学历，1 年以上 NLP / LLM 领域一线研发经验。\n2. 对大模型 Post-Training 阶段有全局视角的理解，曾作为核心骨干完整参与过百亿/千亿级别模型的 SFT 与 RLHF 迭代过程；熟练掌握主流对齐算法（SFT、DPO、GRPO、PPO 等）及其底层数学逻辑。\n3. 有 Reward Model 训练和评估经验，了解偏好学习的常见方法和挑战；对高质量数据有极高的敏锐度，能通过实验快速验证数据配比对模型能力的影响并总结为方法论。\n4. 熟练掌握 PyTorch，有大规模分布式训练经验，熟悉主流训练与推理框架，能快速定位并解决大规模训练中的工程问题。\n5. 对解决具有挑战性的技术问题充满热情，有开源社区贡献（如大模型相关项目）者优先。\n6. 关注领域前沿，有 NeurIPS / ICML / ICLR / ACL / CVPR 等顶会论文发表者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100029700001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型训练Infra工程师-容器Infra方向","city":"北京/杭州","category":"技术-基础平台","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100029700001&track_id=SSP1791223738400sGpEqdGQOB9329","duty":"1. 基于开源 Kubernetes 构建面向大模型训练的容器化基础设施增强能力，研发 GPU 拓扑感知调度、Gang 调度、资源碎片治理与利用率提升，保障千卡 / 万卡级作业的快速拉起与高吞吐运行。\n2. 研发面向训练作业的任务编排与作业管理能力（作业生命周期管理、作业全链路追踪等自定义控制器），支撑预训练、RL、评测多场景任务的可靠调度与快速恢复。\n3. 建设训练算力的资源效率体系，负责容量规划、资源配额预分配与预检、按水位的动态分配 / 变更 / 释放，治理任务间资源争抢，并解决跨集群 Checkpoint 迁移等人工低效问题。\n4. 建设训练镜像加速（镜像构建、分层与压缩、按需加载、P2P、Region 级缓存与预热）与容器存储 / 网络优化能力，缩短作业启动与数据加载时延。\n5. 负责多集群、多算力池的接入与弹性对接（AI 算力池对接、GPU 多地域弹性），建设环境工程（跨域网络、环境交付、可用性巡检），沉淀可复用平台能力与自动化运维。","requirements":"1. 计算机、软件工程等相关专业本科及以上学历，2 年以上容器、云原生或大规模基础设施研发经验。\n2. 熟练掌握 Go 语言，具备扎实的 Linux 系统基础（网络栈、文件系统、cgroups、进程管理），有复杂分布式系统的调试与问题定位能力。\n3. 对 Kubernetes 架构有深入理解，熟悉 Controller / Operator / Scheduler 扩展开发与 CRD / API 扩展机制，有自定义调度器或控制器研发经验；了解容器 Runtime（containerd / CRI）原理。\n4. 具备以下至少一个方向的深度实践经验：\n\ta. 大规模 GPU 调度与资源效率（拓扑感知、Gang 调度、配额管理，如 Koordinator、Volcano、Kueue 等）；\n\tb. 训练 / AI 任务编排与作业生命周期管理（Kubeflow Training Operator、JobSet 等）；\n\tc. 容器镜像加速与分发（Dragonfly、Nydus、Overlaybd 等）或多集群 / 跨域算力接入（Karmada、Cluster API 等）。\n5. 了解大模型训练的资源特征（GPU 拓扑、通信模式、Checkpoint 等），有 AI Infra 相关工程经验者优先。\n6. 良好的工程素养与协作沟通能力，能在快迭代、多团队协作的训练 Infra 场景中稳定交付。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100029400001","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-技术产品专家（TPD）-ModelScope魔搭","city":"北京/杭州","category":"产品类-平台型","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100029400001&track_id=SSP1791223738767cxFiTtPuaO1863","duty":"本职位为ModelScope魔搭平台与社区等技术产品岗（TPD），负责ModelScope魔搭技术生态的产品设计，覆盖魔搭站点、服务以及开源技术生态等全方面。候选人将与魔搭技术研发团队、以及运营团队等紧密合作，同时与相关模型算法团队密切沟通，共同把握魔搭技术发展发向，确保魔搭技术生态整体健康发展。在这个过程中，候选人将深入洞察开发者需求，并结合横向竞品分析等方式，围绕开发者社区核心价值，设计相关产品功能。\n日常工作包括，梳理魔搭平台与站点(modelscope.cn)功能，设计后转化成具体产品PRD文档，并进行工作项拆解，与研发团队对齐研发和上线节奏；与研发团队共同设计魔搭开源生态工具链接口以及在平台上实现服务化的对接设计；明确平台与底层云基座之间的交互协作，确保云平台对于魔搭的支撑；等等。","requirements":"1、硕士及以上，计算机或相关专业毕业。具备AI领域里算法或工程背景，熟悉掌握Python等编程语言。对PyTorch，HuggingFace等框架和工具有深入了解。在面对开发者设计的系统API，以及程序接口实现方面，有相关经验。能够独立撰写面向开发者的技术文档。具备相关领域开源项目贡献经验者为佳。\n2、具备AI领域基础知识，同时对于LLM、Diffusion等不同领域大模型，以及对应的框架、工具生态以及上游Agent应用链路和生态，能保持敏锐的洞察和旺盛的好奇心。理解AI开发者并了解AI开发流程，对社区类平台或开源产品的产品特点及用户需求有深入理解。\n3、具备良好的逻辑分析与表达能力，文字能力优秀，具备较好的英文读写能力。\n4、具备多团队协调能力，目标结果导向，有较强的沟通表达和项目管理能力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100019780005","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-网络安全大模型算法工程师-Qwen","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100019780005&track_id=SSP1791223738767TenwUAlOWf7585","duty":"网络安全是大模型 Agent 能力的重要应用场景，也是检验和提升模型能力的重要方向。我们致力于提升模型在网络安全任务中的表现，推动大模型在智能安全领域的研究与应用。\n\n1. 参与模型在网络安全方向的后训练与强化学习，提升模型完成安全任务的能力。\n2. 构建网络安全任务的训练环境和评测环境，包括网络安全靶场、漏洞复现、补丁验证、攻防演练等。\n3. 探索网络安全任务中的有效训练方法，推动模型能力在真实网络场景中的持续改进。","requirements":"1. 在LLM、RL、Agent领域有相关经验，拥有独立思考与良好团队合作精神。\n2. 对网络安全有兴趣或经验，比如在各大知名CTF比赛中获得过前五名次，或者在软硬件系统中挖掘到高危零日漏洞。\n3. 具备扎实的机器学习与深度学习基础，能够熟练使用PyTorch。\n4. 硕士或博士学位优先，特别优秀者可适当放宽学历要求。\n\n加分项\n1. 曾发表顶级会议论文并具有一定的学术影响力，包括但不限于 S&P，USENIX Security，CCS，NDSS，NeurIPS，ICML和ICLR等顶会。\n2. 拥有知名开源项目，在开源社区具有较好的影响力，或在竞赛中获得引领性的研究成果。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:7000031308","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型评估系统算法工程师-Qwen","city":"北京/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=7000031308&track_id=SSP1791223738767izSsuvgdZG4068","duty":"1. 挖掘大模型弱点，持续快速构建覆盖各项模型能力的评测数据集，探索可靠、具有可扩展性的评测方案。\n2. 参与 LLM-as-a-Judge 方案构建，训练 LLM Judge / Reward Model，建模人类偏好并提升长尾任务的评价准确性。\n3. 参与 Reward System 构建，设计 Reward Signal、合成对应数据，并通过 RL提升模型的能力上限。\n4. 参与开发 Evaluation、Reward System 所需工程框架，简化各类测试任务和模型集成流程，帮助提高团队效率。","requirements":"1. 学历与计算机、机器学习等方向相关，博士及硕士优先。\n2. 了解 LLM Evaluation（评测方案与评测数据构建）或具有 Post-training（SFT、RL等）训练和数据合成经验。\n3. 精通 Python 以及 Pytorch 等深度学习框架。\n4. 熟悉 Transformer 架构以及大语言模型基础知识。\n\n加分项：\n1. 具有较强的代码工程能力。\n2. 曾发表顶级会议论文并具有一定的学术影响力，包括但不限于 NeurIPS、ICLR、ICML、ACL等。\n3. 拥有知名开源项目，在开源社区具有较好的影响力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100023600006","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-Reward System算法工程师-Qwen","city":"北京","category":"技术-研究","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100023600006&track_id=SSP1791223738767UwCRuWnqJu6427","duty":"负责 Qwen 基座模型 Agentic Reward System 的设计、训练与迭代，构建支撑大规模 Agentic RL 训练的奖励信号体系，持续提升模型在 Coding、Agent 等高价值场景下的对齐质量与 RL 训练上限。\n1. Coding Reward System：构建面向 Code Agent 的 Reward System，设计 Evolving Rubrics 与 Code Verifier，实现 Outcome & Process Level 的自动化 Rewarding，解决长程 Coding Trajectory 下的 Credit Assignment 与 Reward 稀疏性问题。\n2. Agentic User Experience Reward：研究面向 Agent 任务的用户体验建模与 Reward 优化，探索 User Model Rewarding 与 Behavioral Signal Mining，弥合 Benchmark指标与用户实际体验之间的鸿沟。\n3. Reward System Infra：以 Reward 信号为核心构建数据飞轮，驱动数据筛选、难例挖掘与合成迭代；建设统一的 Reward 评估与标注框架，与 CPT / SFT / RL训练流程深度耦合，端到端优化全链路传导效率。","requirements":"1. 计算机、人工智能等相关专业硕士及以上学历, 具备相关领域的顶会论文发表优先。\n2. 扎实的工程能力，有工业界大语言模型SFT / RL 训练经验的优先（熟悉 PPO / GRPO 等完整流程）。\n3. 对 Reward System 有独立的技术判断，能分析不同技术路线（Scalar RM / Gen RM / Pair-wise RM 等）的适用边界。\n4. 有以下任一方向的深入经验者优先：\n（1）Reward Model Training（Agent RM / Coding RM / Agentic RM）\n（2）Coding / Agent  Benchmark\n（3）Credit Assignment / Reward Shaping / Multi-turn RL","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100015600002","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型Post-training算法工程师-Qwen","city":"北京/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100015600002&track_id=SSP1791223738767BjExGmgqYz7613","duty":"千问（Qwen）是由通义实验室自主研发的超大规模语言模型，具备跨语言、跨任务的理解与生成能力。Qwen系列模型，涵盖参数量从几百 M 到 T 级的基座大语言模型，并相继推出Qwen-VL、Qwen-Audio、Qwen-Omni、Qwen-Coder、Qwen-Image等系列模型。从多轮对话到代码生成，从逻辑推理到内容创作，从单一多模态到全模态统一理解生成，Qwen 正在打造全球领先的全模态模型技术体系，推动AI在企业服务、开发者生态、个人用户等领域的深度应用，引领下一代人工智能的发展。\n在蕴含丰富世界知识的预训练模型的基础上，我们利用 Post-train 打造出我们想要的能够服务人类的 AI 模型。我们通过 RL、SFT、RFT 等技术，探索大模型潜能的同时，也在塑造大模型的能力与性格。本着为人类服务的目标，我们的 Post-train 将会重点探索其推理能力，实现深度思考，并致力于提升其 Agent 能力，让大模型服务于真实世界的任务。\n\n工作职责：\n1. 探索更多可 scalable 的 verifier 信号，并通过 RL 提升模型的各项能力。\n2. 提升 reward model 在创作、人类偏好、指令遵循等各专项上的能力，减少reward hacking和bias。\n3. 研究 reasoning path压缩和外推，实现更高质量的推理思考。\n4. 将LLM的推理能力和Agent以及其他模态相结合，探索统一模态的reasoning。","requirements":"1. 计算机、机器学习等方向相关专业，博士及硕士优先。\n2. 具有 post-training 或强化学习相关方向经验。\n3. 精通 Python 以及 Pytorch 等深度学习框架，具有较强的代码工程能力。\n\n加分项：\n1. 熟悉LLM推理引擎（如vLLM，SGLang）的实现。\n2. 曾发表顶级会议论文并具有一定的学术影响力，包括但不限于NeurIPS、ICLR、ICML、ACL等。\n3. 拥有知名开源项目，在开源社区具有较好的影响力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100024560004","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-训练系统算法工程师-Qwen","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100024560004&track_id=SSP1791223738767PoVsbjzHeQ7313","duty":"1. 训练策略设计与优化： 深入理解预训练与RL后训练（如PPO/GRPO等）算法流程，设计并优化大规模分布式训练策略（3D并行、MoE EP、Context Parallel等），解决RL阶段多模型（Actor/Critic/Rollout/Ref）交互的复杂调度与显存墙问题。\n2. 框架定制与二次开发： 基于主流训练框架（如Megatron-LM, DeepSpeed等），进行应用层和策略层的二次开发与插件编写，快速支持新模型架构（如长文本、多模态、新型MoE）和新优化器（如Muon, SOAP）的落地验证。\n3. 大规模训练稳定性保障（Troubleshooting）： 负责千卡/万卡集群训练的稳定性攻坚。排查并解决训练过程中的Loss Spike、OOM、Hang、通信死锁等疑难杂症，开发自动化诊断、监控与容错恢复工具链。\n4. 跨团队协同与联合调优： 作为算法侧接口人，与Infra团队紧密协同。从算法和框架视角提出性能优化需求，配合底层团队完成算子、通信库及硬件层面的联合Profiling与调优，而非独立承担底层基建开发。\n5. 前沿技术追踪与落地： 跟踪SOTA大模型训练技术，评估新技术在Qwen训练场景下的适用性，推动训练框架在算法侧的持续演进。","requirements":"1. 学历与基础： 计算机科学、人工智能或相关专业本科及以上学历（硕博优先），具备扎实的深度学习理论基础，熟悉Transformer架构及LLM预训练/后训练（RLHF/RL）核心算法。\n2. 框架能力： 深入理解主流大模型训练框架（Megatron-LM, DeepSpeed, FSDP等）的工作机制与架构设计，具备丰富的源码级Debug、二次开发及插件编写能力。\n3. 分布式与调度经验： 熟悉GPU并行计算原理及集合通信原语，具备大规模分布式训练系统设计经验。有RL后训练多模型调度、MoE专家并行（EP）通信优化、或长文本Context Parallel实际落地经验者优先。\n4. 问题排查能力： 具备极强的Troubleshooting能力，熟练使用Nsys、Torch Profiler等工具，能够独立定位并解决大规模集群训练中的性能瓶颈、Loss异常及系统崩溃问题。\n5. 编程与协同： 精通Python。具备极强的跨团队沟通能力和目标导向意识。\n\n加分项：\n1. 具备千卡/万卡规模大模型预训练或RL训练的实际实操与稳定性保障经验。\n2. 在系统顶会（OSDI/SOSP/ASPLOS等）或AI顶会（NeurIPS/ICLR等）发表过相关论文。\n3. 在知名开源大模型训练框架（如Megatron-LM, vLLM等）中有核心代码贡献。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100011920004","sourceKey":"tongyi_social","company":"通义","title":"Token Foundary事业部-多模态通用音频大模型算法工程师/专家-未来生活实验室","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100011920004&track_id=SSP1791223738767dfxiLLPdvp9630","duty":"1. 负责音频生成大模型研发（文生音频、音频编辑、音色克隆、音效合成等），产出高保真、可控的生成方案并推动落地；\n\n2. 研发音频理解大模型，构建跨模态（文本、图像、视频与音频联合）的细粒度音频内容描述体系；\n\n3. 搭建大规模多源通用音频数据集（音乐、语音、环境声等），支撑模型持续迭代；\n\n4. 推动音频大模型在业务场景中落地，解决推理效率、可控性、实时性等工程问题；\n\n5. 跟进行业前沿，保持团队在通用音频大模型领域的技术领先。","requirements":"1、学历经验：硕士及以上，1年以上音频/语音/音乐生成大模型研发经验。\n\n2、核心技术：精通音频生成算法，对DiT、Flow Matching、MLLM、vocoder等技术有自己的理解和实操经验。\n\n3、底层技术：熟悉音频表征（HuBERT/WavLM等）及高音质编解码方案（EnCodec/DAC等），对音质敏感。\n\n4、多模态能力：有 AudioLDM、MusicGen、Qwen-Audio 等多模态音频大模型开发经验者优先。\n\n5、工程与科研：Python/C++ 基础扎实，熟练使用 PyTorch/DeepSpeed；有 ICASSP/Interspeech 顶会论文或乐理/声学背景者加分。\n\n(注：满足以上任意3项即可)","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100007080003","sourceKey":"tongyi_social","company":"通义","title":"Token Foundary事业部-AIGC产品经理 / 高级产品专家（多模态方向）-未来生活实验室","city":"北京/杭州","category":"产品类-用户型","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100007080003&track_id=SSP1791223738767WXfueygkbw7740","duty":"1. 多模态产品规划与落地：负责多模态 AIGC 产品的整体规划、产品架构与能力设计，主导从 0→1 或 1→N 的产品建设与迭代，推动多模态生成技术在真实业务场景中的规模化落地。\n2. 技术能力与业务场景融合：深入理解多模态大模型的能力边界与演进方向，持续挖掘高价值应用场景，将前沿算法能力转化为具备用户价值与商业价值的产品能力。\n3. 跨团队协同与项目推动：作为算法、工程与业务团队之间的核心协同角色，承担“技术翻译”与“方向推动”职责。深度参与模型效果评估、能力定义与迭代策略制定，推动项目高效完成从需求、验证到上线的完整闭环。\n4. 行业洞察与战略判断：持续关注全球多模态 AIGC 领域的技术趋势、产品创新与行业变化，对未来 1-2 年的技术演进与产业机会具备独立判断能力，为产品方向与战略决策提供前瞻性输入。\n\n岗位方向\n● 视频生成模型与产品 HappyHorse\n● 世界模型与交互式产品 HappyOyster\n● 其他创新探索产品......","requirements":"1. 经验背景:3 年以上互联网或 AI 产品经验，具备多模态 AIGC 产品的完整落地经历；有视频生成、多模态模型平台、模型工具链或底层模型相关经验者优先。\n2. 技术理解能力:对多模态 AI 技术具备较强理解力，能够与算法围绕模型生成效果、推理成本、数据质量、能力边界等问题进行深入且专业的讨论。\n3. 前瞻性与行业判断:对多模态大模型及相关前沿方向保持高度敏感，对未来技术演进路线具备独立思考与判断能力；能够穿透技术 hype，理解长期真正有价值的能力与机会。\n4. 综合能力:具备强烈的 Owner 意识与结果导向，能够主动发现问题并推动复杂项目落地；逻辑清晰、沟通高效，具备优秀的判断力与协同能力，能够在算法、产品与用户之间承担关键“翻译层”与“决策层”角色。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100011240002","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-语音AI产品经理-Qwen Audio","city":"北京/杭州","category":"产品类-商业型","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100011240002&track_id=SSP1791223738767eiKpCHRZMd4689","duty":"1. 产品规划与路线设计：深度调研不同场景下的语音AI产品需求，结合语音AI技术演进与行业发展趋势，制定语音交互产品（语音输入、语音生成、语音对话、语音同传、歌声音乐生成等）的短中长期路线图，明确核心能力优先级、场景落地顺序及资源投入节奏。\n2. 功能设计与优化：主导语音AI产品核心功能的设计与迭代，包括但不限于：语音音色设计、交互体验设计、场景化功能定制，持续提升产品在不同场景下的用户体验。定义和细化语音AI模型的功能和评测体系，包括但不限于：表现力、共情、自然度等。\n3. 跨团队协同与项目推进：作为语音AI产品落地的核心协调者，联动算法、工程、业务及测试团队，明确各环节交付标准与时间节点，解决跨部门协作中的技术瓶颈与需求冲突，确保产品在各场景顺利落地。\n4. 行业动态与竞品分析：跟踪国内外语音AI技术与产品的发展动态（如新型算法、前沿应用场景、竞品功能与策略等），定期输出分析报告，为产品策略调整提供依据，提升公司语音AI产品的竞争力。","requirements":"1. 经验背景：3年及以上产品经理工作经验，其中至少2年以上语音相关产品经验，有TTS、语音翻译等经验者优先。熟悉语音AI技术的基本原理与产品开发流程，有操盘语音AI产品在2B服务经验的优先。\n2. 技术理解能力：具备对语音AI技术的基础认知，能理解算法技术概念，可与算法、工程团队高效沟通技术方案的可行性、落地成本及优化方向。\n3. 跨团队协作能力：具备强沟通协调能力与项目推动力，能在多团队协作中明确目标、化解分歧，过往有主导跨部门复杂项目落地的经验。\n4. 问题解决与抗压能力：面对产品落地中的技术瓶颈、资源冲突，能快速拆解问题、提出替代方案；可适应快节奏的产品迭代节奏，承受项目交付压力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100011720034","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型音视频理解算法工程师-Qwen","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100011720034&track_id=SSP1791223738767NXdsxjGjcO2373","duty":"1. 音频/音视频 Agentic能力: 原生音视频Agentic/Long-horizon, 全模态Agentic/Coding不降智等。\n2. 音视频理解基础能力：包括Caption, Grouding, 音视频Alignment， General QA，长视频，多音视频理解等。\n3. 音频/语音理解基础能力: 包括ASR, MultiSpkASR, 语音/音频Grouding/Counting/QA，音乐理解，长音频，多音频理解等。\n4. 音频/音视频Postrain/RL/OPD。\n5. 音视频通话与交互：包括全音视频双工, 音频query不降智/体感优化等。\n6. 语音生成基础能力: 包括音色克隆，可控性，长语音生成稳定性等。\n7. 全模态模型自主优化与Self-evolving。","requirements":"1. 计算机、机器学习等相关专业，博士及硕士优先。\n2. 较强的代码能力，具有丰富的 TTS / Codec / 流ASR 研究经验，具有相关数据处理经验。\n3. 精通 Python 以及 Pytorch 等深度学习框架。\n4. 熟悉 Transformer 架构以及大语言模型基础知识。\n5. 善于平衡研究目标及落地实现，且结果导向。\n6. 良好的沟通和合作能力。\n7. 关注技术影响力，具有开源开放精神。\n\n加分项：\n1. 曾发表顶级会议论文并具有一定的学术影响力，包括但不限于 NeurIPS、ICLR、ICML、ACL、CVPR、ECCV、InterSpeech 等，具有一些有深度的研究工作是较大加分项，欢迎其他方向的多模态同学看音频方向的机会。\n2. 具有较强的工程能力，有开发音视频实时交互系统的经验。\n3. 具有高表现力/鲁棒 TTS 生成模型研究/开发经验。\n4. 具有持续打磨好每一个技术细节的钻研精神。\n5. 拥有知名开源项目，在开源社区具有较好的影响力。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100012520008","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-大模型评测与对齐算法专家-Qwen","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100012520008&track_id=SSP1791223739094mmaGvRzReU7423","duty":"1. 负责建设面向集团各业务线的大模型评测体系，涵盖通用能力评测与业务场景定制评测，优化基于 LLM-as-Judge、自动化评测模型训练、人工评估和用户行为数据的多维度评测框架，保障评测结果的全面性和可靠性。\n2. 构建多维度评测指标体系（准确性、安全性、流畅度、一致性、业务指标等），覆盖 APP 对话助手及各业务线智能体场景。\n3. 深度参与模型迭代过程中的评测驱动优化，建设完整的“数据→训练→评测→反馈”的高效数据飞轮。\n4. 跟踪业界主流评测方法与 Benchmark 动态，持续优化内部评测体系。","requirements":"1. 计算机科学、人工智能等相关专业硕士及以上学历，1 年以上大模型研发相关工作经验。\n2. 了解 LLM 常见的能力维度（推理、知识、指令遵循、安全、多轮对话等）及对应的评测策略。\n3. 具备大模型评测体系设计与落地经验，熟悉主流 Benchmark 与评测框架，有 Rubrics 评测、Arena 对战评测等评测方法实践经验者优先。\n4. 较强的数据分析能力、优秀的沟通能力与业务理解力，能够从评测数据中提炼模型短板、定位根因、驱动优化方向，能与产品、业务团队有效对齐评测标准。\n5. 对解决具有挑战性的技术问题充满热情，有开源社区贡献（如大模型相关项目）者优先。\n6. 关注领域前沿，有 NeurIPS / ICML / ICLR / ACL 等顶会论文发表者优先。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:100022900018","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-RLHF 算法专家-Qwen","city":"北京/杭州","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=100022900018&track_id=SSP1791223739094migMXXahVW2961","duty":"1. 用户偏好采集与建模：设计并构建系统化的用户偏好数据采集方案，深入分析用户行为与反馈信号，建立多维度、可扩展的用户偏好表征与建模体系，为 Reward Model 训练提供高质量数据基础。\n2. Reward Model 训练与优化：训练高精度、低偏差的 Reward Model，覆盖创作质量、指令遵循、安全对齐、人类偏好等多个专项维度；持续优化训练策略，有效缓解 Reward Hacking 与分布偏移问题，为下游 RL 训练（PPO / GRPO 等）和用户偏好评测提供可靠的奖励信号。\n3. 用户反馈分析与 Badcase 聚类：建立从线上用户反馈到模型迭代的闭环机制，利用聚类、归因分析等方法系统性挖掘 Badcase，定位模型能力短板与偏好盲区，驱动数据策略与训练目标的持续优化。\n4. LLM Judge / Verifier 体系建设：研究并构建基于 LLM 的自动化评测与验证体系，设计可 Scalable 的 Verifier 信号，使其既能作为高效的偏好评测工具，也能作为奖励信号直接融入 RL 训练流程，提升模型迭代的自动化程度与覆盖广度。\n5. 偏好对齐前沿探索：持续跟踪 RLHF / RLAIF / DPO / Constitutional AI 等对齐技术的前沿进展，探索更高效的偏好学习范式，推动 Qwen 在对齐质量与训练效率上的双重突破。","requirements":"1. 计算机、机器学习、人工智能、自然语言处理等相关专业，硕士及以上学历。\n2. 具有 RLHF / Reward Modeling / 偏好对齐方向的实践经验，熟悉 PPO、DPO、GRPO 等主流算法的原理与工程实现。\n3. 精通 Python 及 PyTorch 等深度学习框架，具备扎实的工程能力，能够独立完成从数据处理、模型训练到评测部署的全链路工作。\n4. 对数据质量高度敏感，具备优秀的数据分析与问题诊断能力，能够从复杂反馈信号中提炼有效的优化方向。\n\n加分项\n1. 熟悉主流 RL 训练框架（如 veRL ）及大规模分布式训练方案（DeepSpeed、Megatron-LM、FSDP）。\n2. 在 Reward Model 泛化性、Reward Hacking 缓解、偏好数据合成等方向有深入研究或实际落地经验。\n3. 曾在 NeurIPS、ICLR、ICML、ACL 等顶级会议发表对齐、强化学习或 NLP 相关论文，具有一定学术影响力。\n4. 拥有知名开源项目贡献经历，在开源社区具有较好的影响力。\n5. 具备线上系统用户反馈分析经验，熟悉 A/B 测试、用户行为建模等方法论。","description":"","jdComplete":true,"sourceStatus":null},{"id":"tongyi_social:7000033602","sourceKey":"tongyi_social","company":"通义","title":"Token Foundry-视觉语言大模型算法工程师-Qwen","city":"北京/杭州/上海","category":"技术类-算法","channels":["social"],"employment":null,"talentPlan":null,"date":null,"dateKind":null,"url":"https://careers-tongyi.alibaba.com/off-campus/position-detail?positionId=7000033602&track_id=SSP1791223739094ahIZPUnHCF5698","duty":"1. 多模态Pre-training：开展研究及进行实验。研究内容包括：数据清洗与筛选、数据配比优化、课程学习、视觉语言模型结构设计与优化、训练策略优化、预训练数据合成、scaling law预测、词表优化、模型蒸馏与压缩、长上下文能力优化等。\n2. 多模态Post-training：迭代Post-training训练策略（SFT/RLHF），专项能力数据迭代，参与模型能力评测及评测数据和评估标准的迭代。\n3. 多模态推理和通用Agent：通过强化学习（RL）持续提升多模态模型推理能力和执行任务能力，打造多模态的Test Scaling Laws，并推动模型对网络和虚拟世界的交互和任务完成能力。\n4. 统一理解生成：构建视觉统一理解生成大模型，推进多模态统一生成与理解的推理和交互新范式。","requirements":"1. 计算机科学、计算机视觉、人工智能、机器学习、具身智能等领域的博士/硕士毕业生。\n2. 较强的代码能力，擅长模型训练及数据处理；精通Python及PyTorch等深度学习框架；熟悉Transformer架构以及CV、大语言模型基础知识。\n3. 善于平衡研究目标及落地实现，具备跨学科视野与协作意识，能够与工程、产品等多学科团队紧密合作，推动研究成果快速落地并产生实际影响力。\n4. 关注技术影响力，具有开源开放精神，对基础模型的前沿问题有持续热情，具备独立思考能力和系统性研究思维，敢于挑战现有范式，能够独立应用技术解决复杂问题。\n\n加分项\n1. 曾发表顶级会议论文并具有一定的学术影响力，包括但不限于：CVPR、ECCV、NeurIPS、ICML、ICLR、ACL、TPAMI等国际顶级计算机会议/期刊。\n2. 拥有知名开源项目，在开源社区具有较好的影响力，或在竞赛中获得引领性的研究成果。\n3. 具有大规模预训练实战经验。","description":"","jdComplete":true,"sourceStatus":null}];
